(window.TNQ=window.TNQ||[]).push({"terms":{"본질안전 방폭구조":{"d":"전기 불꽃과 열이 가스를 점화할 수준에 이르지 않게 한 방폭구조이다.","r":[]},"파이프 서포트":{"d":"거푸집을 아래에서 받치는 길이 조절 강관 지지대이다.","r":[]},"평형플랜지":{"d":"연삭숫돌을 양쪽에서 고르게 잡아 주는 고정판이다.","r":[]},"안전밸브":{"d":"압력이 한도를 넘으면 열려 압력을 내보내는 밸브이다.","r":[]},"띠장":{"d":"비계기둥을 가로로 이어 주는 수평 부재이다.","r":[]},"휘도":{"d":"면이 단위 면적당 반사하거나 내는 빛의 양이다.","r":[]},"분진폭발":{"d":"가연성 가루가 공기 중에 퍼져 불이 붙어 폭발하는 현상이다.","r":[]},"검전기":{"d":"전로에 전기가 흐르는지 확인하는 기구이다.","r":[]},"심실세동":{"d":"심장 근육이 떨기만 해 피를 내보내지 못하는 상태이다.","r":[]},"MTTF":{"d":"고장 날 때까지의 평균 시간이다.","r":[]},"분할날":{"d":"둥근톱에서 일감이 톱날을 물지 않도록 뒤쪽에 두는 판이다.","r":[]},"양수조작식":{"d":"두 손으로 동시에 조작해야 작동하는 방호장치이다.","r":[]},"제전기":{"d":"정전기를 없애는 장치이다.","r":[]},"페일세이프":{"d":"고장이 나도 안전한 쪽으로 작동하게 하는 설계이다.","r":[]},"피뢰기":{"d":"번개 같은 높은 전압을 땅으로 흘려 설비를 지키는 장치이다.","r":[]},"안전기":{"d":"용접 때 불꽃이 거꾸로 들어가는 것을 막는 장치이다.","r":[]},"HAZOP":{"d":"공정의 이상 상황을 말 단위로 찾아 평가하는 위험성 평가 기법이다.","r":[]},"보통꼬임":{"d":"로프의 꼬임과 가닥의 꼬임이 반대 방향인 꼬임이다.","r":[]},"지중경사계":{"d":"땅속에서 수평 변위를 재는 계측기이다.","r":[]},"페이퍼드레인":{"d":"종이 배수재로 점토층의 물을 빼는 지반 개량 공법이다.","r":[]},"샌드드레인":{"d":"모래 기둥으로 점토층의 물을 빼는 지반 개량 공법이다.","r":[]},"워크레스트":{"d":"연삭기에서 일감을 받치는 대이다.","r":[]},"손쳐내기식":{"d":"슬라이드가 내려오기 전에 손을 밀어내는 방호장치이다.","r":[]},"기상폭발":{"d":"기체 상태에서 일어나는 폭발이다.","r":[]},"안전블록":{"d":"프레스 금형 작업 중 슬라이드가 내려오지 않게 받치는 블록이다.","r":[]},"표준관입시험":{"d":"샘플러를 박는 타격 횟수로 지반 강도를 재는 시험이다.","r":[]},"스트리머 코로나":{"d":"코로나 방전 진전 과정에서 나타나는 가지 모양 방전이다.","r":[]},"4M":{"d":"재해의 기본 원인인 Man Machine Media Management이다.","r":[]},"폭연성 분진":{"d":"폭발하기 쉬운 성질을 가진 분진이다.","r":[]},"단열압축":{"d":"열 출입 없이 기체를 압축해 온도가 오르는 과정이다.","r":[]},"금수성 물질":{"d":"물과 접촉하면 위험한 가스를 내는 물질이다.","r":[]},"전격":{"d":"전류가 몸에 흘러 받는 충격이다.","r":[]},"플레어스택":{"d":"남는 가스를 안전하게 태워 처리하는 설비이다.","r":[]},"일함수":{"d":"물질에서 전자를 떼어 내는 데 필요한 에너지이다.","r":[]},"소성가공":{"d":"재료를 눌러 모양을 바꾸는 가공이다.","r":[]},"하이드로포밍":{"d":"액체 압력으로 금속관을 성형하는 소성가공이다.","r":[]},"방호장치":{"d":"기계의 위험 부위로부터 사람을 보호하는 장치이다.","r":[]},"차압식":{"d":"압력 차이로 유량을 재는 방식이다.","r":[]},"RULA":{"d":"작업 자세의 부담을 평가하는 인간공학 기법이다.","r":[]},"씰링피팅":{"d":"방폭 배관에서 가스가 번지지 않게 밀봉하는 부품이다.","r":[]},"점성토":{"d":"점착성이 커서 물을 머금는 진흙 성질의 흙이다.","r":[]},"지락":{"d":"전기가 땅으로 새는 사고이다.","r":[]},"단락":{"d":"전선이 합선되는 사고이다.","r":[]},"권과방지장치":{"d":"크레인 후크가 너무 올라가는 것을 막는 장치이다.","r":[]}},"notes":{"(P1/P2)를 쓴 식은 틀린 식이다":"압력비를 거꾸로 쓴 식은 단열압축 후 온도 식으로 맞지 않습니다.","-30℃ 이상 0℃ 미만이다":"아세톤의 인화점이 속하는 온도 범위를 나타냅니다.","0등급 흰색과 1등급 노란색은 틀린 연결이다":"절연장갑 등급과 색의 대응이 잘못되었습니다.","0종과 23종은 분진폭발위험장소 분류가 아니다":"분진폭발 위험장소는 이 두 가지 구분을 쓰지 않습니다.","0종 위험장소에서도 사용할 수 있다":"본질안전방폭구조는 폭발 위험이 가장 큰 곳에서도 쓸 수 있는 구조입니다.","1.3kgf/cm² 이상 압력으로 쓰지 않는다":"아세틸렌은 높은 압력에서 위험하므로 용접용 사용 압력에 한도가 있습니다.","10% 넘게 줄거나 균열이 있으면 폐기한다":"체인의 링 단면이 닳거나 금이 가면 쓰지 못합니다.","1000Hz 이상을 쓰지 않는다":"멀리 전달해야 하는 소리는 높은 주파수가 쉽게 줄어 쓰지 않습니다.","1000mg/kg 이하인 물질이다":"쥐 피부 투여 기준에서 급성독성물질로 보는 한계입니다.","100cm나 120cm가 아니다":"충전전로에 접근할 수 있는 한계거리가 이 수치가 아니라는 설명입니다.","10cm 이상이고 100kg 하중에 견딘다":"발끝막이판은 물건이 떨어지지 않게 일정 높이로 하고 하중에 견뎌야 합니다.","10m나 20m, 25m 초과":"이 풍속들은 타워크레인 운전 중지 기준이 아닙니다.","120SPM 이상 포지티브클러치에 적용된다":"양수조작식은 포지티브 클러치 프레스에 쓰며 분당 행정 수 기준이 있습니다.","120SPM 이하의 프레스에 적합하다":"수인식은 속도가 너무 빠른 프레스에는 맞지 않습니다.","150Lux 이상의 조도에서 조작한다":"전기기계 조작 부분은 어두우면 위험하므로 충분히 밝아야 합니다.","15mA·0.1초와 50mA·0.5초":"감전방지용 누전차단기의 감도와 동작시간 기준으로 맞지 않는 조합입니다.","1:4 이상인 구조물도 확인한다":"가늘고 높은 구조물은 바람에 약해 내력을 점검합니다.","1mm 이상 손상이 있으면 폐기한다":"D링이 이만큼 상하면 쓰지 않습니다.","1개는 최고사용압력 이하, 1개는 1.05배 이하에서 작동한다":"방출장치를 둘 설치하면 작동하는 압력을 다르게 정합니다.","1개소 이상 절단되면 폐기한다":"벨트를 꿰맨 실이 끊어지면 버립니다.","1년에 1회 이상 교정된 압력계로 토출압력을 시험한다":"압력방출장치는 해마다 압력계로 작동 압력을 확인합니다.","1단계는 사회적 환경 및 유전적 요소":"하인리히 도미노에서 사고의 시작은 사회 환경과 타고난 요소입니다.","1이며 A·A'은 1이 아니다":"불대수에서 A와 A의 부정을 더하면 1이 되고 곱하면 1이 되지 않습니다.","1주 36시간과 1일 8시간":"고압작업 근로시간을 이렇게 정한 것은 틀립니다.","20m 이상 구조물은 풍압 내력을 확인한다":"높은 철골 구조물은 바람의 힘을 견디는지 따져 보아야 합니다.","220V에 인체저항 약 1000Ω이면 220mA가 흐른다":"220을 1000으로 나눈 값에 해당하는 전류가 몸에 흐릅니다.","2개 이상의 지지물에 고정한다":"발판이 흔들리거나 벗어나지 않도록 지지물 두 곳 이상에 묶어 둡니다.","2년마다 1회 이상인 경우가 있다":"안전밸브 검사는 조건에 따라 이 주기로 하기도 합니다.","2년에 1회 이상 일반건강진단을 한다":"사무직 근로자의 일반건강진단 주기입니다.","300mg/kg 이하인 물질이다":"급성독성물질의 쥐 경구 투여 반수치사량 기준입니다.","300톤급 이상 선박에서 하역 시 설치한다":"큰 배에서 하역할 때는 오르내릴 수 있는 설비가 필요합니다.","30cm 굴진에 필요한 타격횟수이다":"표준관입시험의 N값은 샘플러를 30cm 박는 데 필요한 타격 횟수입니다.","30℃ 이상 65℃ 이하이다":"아세트산의 인화점이 속하는 온도 범위를 나타냅니다.","34시간을 초과해서는 안 된다":"일주일 동안 고압 작업을 할 수 있는 시간의 한도입니다.","3단계는 불안전한 행동 및 상태":"사고 직전 단계는 사람의 불안전한 행동과 환경입니다.","50kg/m² 이하도 대상이다":"철골이 적게 쓰인 가벼운 구조물도 내력 확인 대상입니다.","600V 이상은 아크 화상 방지 조치를 한다":"충전전로 작업에서 고전압이면 불꽃으로 인한 화상 예방을 해야 합니다.","7% 넘게 줄어든 로프는 쓰지 않는다":"항타기 와이어로프의 지름이 많이 줄었으면 교체합니다.","7.5R 4/14이며 화학물질 취급장소의 유해·위험 경고에 쓴다":"안전·보건표지의 빨간색을 표준 색도로 나타낸 것입니다.","75cm나 50cm 기준은 틀리다":"부두 하역 통로 폭 기준으로 이 수치는 맞지 않습니다.","7m 이내마다 계단참을 둔다":"높이가 높은 비계다리는 오르내리다 쉴 수 있도록 일정 높이마다 계단참을 둡니다.","82cm 이상 높이로 울타리를 설치한다":"승강설비 양옆은 추락하지 않게 높이 기준 이상의 울타리를 둡니다.","90cm 정도 높이의 안전난간을 설치한다":"덮개를 씌울 수 없는 개구부는 난간으로 둘러 추락을 막습니다.","MTTF×(1＋1/2＋…＋1/n)이다":"지수분포를 따르는 병렬계의 평균 수명은 부품 수에 따라 이 식으로 늘어납니다.","MTTF×n이나 MTTF×1/n":"병렬계 수명을 이렇게 곱셈으로만 표현한 식은 틀립니다.","Method는 4M이 아니다":"재해 기본원인 4M에는 방법이 아닌 다른 요소가 들어갑니다.","RULA는 인간공학적 평가기법이다":"RULA는 작업 자세가 몸에 주는 부담을 평가하는 방법입니다.","fool proof와 점검표로 대비한다":"휴먼에러 대책으로 실수해도 안전한 장치와 점검표를 씁니다.","moving scale형은 표시장치 면적을 최소화할 수 있다":"동목형은 눈금이 움직여 좁은 공간에서도 넓은 범위를 나타냅니다.","plug flow reactor이다":"연속식으로 넣고 빼는 관형 반응기를 부르는 영어 이름입니다.","가공기계의 금형 가드·인터로크 장치·이중촬영방지기구 등이다":"풀 프루프는 사람이 실수해도 사고가 나지 않게 하는 장치들입니다.","가공물 낙하에 의한 위험을 막는다":"방호장치는 가공물이 떨어져 생기는 사고를 막습니다.","가공전선 인입구·인출구와 배전용 변압기 고압측에 설치한다":"발전소와 변전소의 전선 입구, 출구와 변압기 고압 쪽에 둡니다.","가는 관으로 된 긴 형태이고 처리량이 많다":"관형반응기는 관 모양이라 연속적으로 많은 양을 처리하기 쉽습니다.","가능한 한 관성을 이용하고 공구의 기능을 결합한다":"동작경제는 반동을 이용하고 여러 기능을 한 공구로 합치는 방법을 씁니다.","가벼운 불연성 재료로 하며 견고한 콘크리트로 하지 않는다":"가스장치실은 폭발 시 압력이 빠져나가도록 가벼운 불연재로 만듭니다.","가벼운 재료로 폭발구를 둔다":"건조설비 윗부분에는 폭발 압력이 빠져나가도록 약한 재료로 구멍을 만듭니다.","가스가 발생하거나 정체할 위험이 있는 장소에서 측정한다":"가스가 생기거나 고이기 쉬운 곳에서 측정해야 합니다.","가스 농도 2% 이하 대기에서 쓴다":"방독마스크는 고농도 가스가 아닌 일정 농도 이하 환경에서만 사용합니다.","가스 누출이 의심되거나 이상을 발견하면 측정한다":"누출이 의심되면 곧바로 농도를 잽니다.","가스 발화온도에 따라 T1~T6으로 나눈다":"방폭기기 표면 온도는 가스가 불붙는 온도에 맞춰 등급을 나눕니다.","가스용기·탱크 등은 접지하고 배관 내 유속을 제한한다":"금속 도체 설비는 접지로 전기를 빼내고 흐름 속도를 제한합니다.","가스집합 용접장치도 대상이다":"가스를 모아서 쓰는 용접장치도 계획서 제출 대상에 들어갑니다.","가스 포집기를 이용한 검지관 방법이다":"가스를 모아 검지관에 통과시켜 농도를 확인하는 방식입니다.","가스폭발보다 불완전 연소가 쉬워 연소 후 가스 중독 위험이 있다":"분진은 산소 공급이 모자라 덜 타므로 타고 난 뒤 일산화탄소 중독이 생길 수 있습니다.","가연성 가스가 장기간 체류하는 곳과 설비 내부 등이다":"가장 위험한 종별 장소로, 폭발성 가스가 계속 있거나 오래 머무는 곳입니다.","가연성가스·액체의 위험특성 확인과 위험장소 종별·범위 결정":"방폭설비 선정에 앞서 위험 물질과 장소를 먼저 정합니다.","가연성가스·증기가 폭발한계 내에 있을 때 위험하다":"연료 농도가 폭발 범위 안에 있어야 불이 붙습니다.","가연성 기체 분출 화재에 주 밸브를 닫아 공급을 막는다":"제거소화는 타는 물질을 없애는 것으로, 가스 화재에서는 공급 밸브를 잠급니다.","가연성이면서 독성 가스이고 불연성 가스가 아니다":"일산화탄소는 불에 타며 독성도 있는 가스입니다.","가연성 증기·가스가 체류하는 장소와 화약류 장소에 설치하지 않는다":"수신부 안에 불꽃이 생길 수 있으므로 폭발 위험이 있는 곳에는 설치하지 않습니다.","가열 부위와 감전 우려 부위에 설치한다":"뜨겁거나 전기가 흐를 수 있는 부분을 덮개로 가립니다.","각 단마다 압력방출장치를 설치한다":"압축기를 여러 단으로 이으면 단마다 방출 장치가 필요합니다.","간단해 비전문가도 짧은 훈련으로 쓸 수 있다":"FMEA는 서식이 간단해 전문가가 아니어도 쉽게 익혀 쓸 수 있습니다.","간접원인(평가)은 5단계에 없다":"재해 발생 5단계에 간접원인이라는 단계는 없습니다.","감긴 쇠줄은 최소 두 바퀴 이상 남긴다":"로프를 다 풀면 빠질 수 있어 드럼에 일정 감김을 남깁니다.","감성적 리듬은 28일 주기이다":"감성 리듬은 한 달 가까운 주기를 가지고 반복됩니다.","감시와 환경은 기본기능 유형이 아니다":"감시와 환경은 인간-기계 체계의 기본 기능 유형에 들지 않습니다.","감시인을 배치하고 잠재위험을 파악하며 충분히 환기한다":"밀폐공간에 들어가기 전에 지킬 안전 조치들입니다.","감응식 방호장치를 쓰며 날 접촉예방장치는 프레스용이 아니다":"프레스에는 사람이 가까이 오면 멈추는 장치를 쓰고, 날 접촉예방장치는 다른 기계용입니다.","감전 위험이 있어 쓰지 않는다":"굵은 물줄기는 전기를 타고 올 수 있어 전기 화재에 쓰지 않습니다.","감전자를 감싸되 상처 부위가 닿지 않게 한다":"체온이 떨어지지 않도록 감싸지만 상처에는 닿지 않게 합니다.","감지, 정보보관, 정보처리 및 의사결정, 행동":"인간-기계 체계에서 사람이 하는 기본 기능 네 가지입니다.","강도와 인성을 높이는 구조의 안전화이다":"열처리로 재료를 단단하고 질기게 하는 것도 구조적 안전화입니다.","강성이 크고 수밀성이 좋으며 정밀도가 높다":"철제 거푸집은 단단하고 물이 새지 않으며 치수가 정확합니다.","강자성체 표면·표층의 결함을 누설자속으로 검출한다":"자분탐상검사는 자성 재료의 표면 결함을 자기장이 새는 것으로 찾습니다.","강재 2.5 이상, 목재 5 이상이다":"달비계의 부재는 재료에 따라 안전율이 다릅니다.","강한 힘을 가하지 않고 드릴날을 손으로 잡지 않는다":"드릴 작업은 무리한 힘을 주지 않고 날은 맨손으로 만지지 않습니다.","갖추고 유지·관리할 수 있어야 한다":"검사에 필요한 장비를 갖추고 관리해야 합니다.","개개인에게 적절한 지도 훈련":"O.J.T는 일하며 사람마다 맞는 지도를 줄 수 있습니다.","개개인의 학습진도를 조절할 수 없다":"강의법은 사람마다 속도를 맞추기 어렵습니다.","개량해 대지 저항률을 낮춘다":"접지극 주변 흙을 개량하면 땅의 저항이 줄어듭니다.","개방계 증기운 폭발이나 분진폭발이 아니다":"BLEVE는 밀폐 용기가 터지는 폭발이어서 개방 증기운이나 분진 폭발과 다릅니다.","개스킷을 쓰고 상호 밀착시킨다":"관 연결 부분은 틈이 없도록 밀봉재를 끼워 붙입니다.","개스킷을 쓰고 주관 및 분기관에 안전기를 설치한다":"관 연결부는 밀봉재로 막고 주관과 분기관에 안전기를 둡니다.","개폐기에 시건장치와 통전금지 표지판을 단다":"작업 중 누가 전기를 넣지 못하도록 개폐기를 잠그고 표지판을 붙입니다.","거푸집 안에서 횡방향으로 이동시키지 않는다":"콘크리트를 부은 뒤 옆으로 끌면 재료가 분리되므로 이동시키지 않습니다.","건망증(Lapse)과 위반(Violation)은 착오와 구분된다":"잊어버린 것과 규칙 어김은 상황을 잘못 판단한 착오와는 다른 유형입니다.","건설기계의 종류 및 성능이 들어간다":"차량계 건설기계 작업계획서에 적을 내용 중 하나입니다.","건조물 · 공장 배치 · 입지조건":"설계 전에 건물과 공장 배치와 입지 조건을 정성적으로 평가합니다.","건조분말·회·마른 모래로 덮고 물을 뿌리지 않는다":"황산이 섞인 화재에는 물이 위험하여 마른 가루나 모래로 덮어 끕니다.","걸쳐 놓은 지점에서 60cm 이상 올라가게 한다":"사다리를 타고 올라가는 사람이 잡을 수 있게 윗부분을 위로 길게 올립니다.","검전기로 충전 여부를 확인한다":"정전 작업 전에 전기가 흐르는지 검전기로 직접 확인합니다.","검전기로 충전 유무를 확인한 뒤 설치한다":"먼저 전기가 없는지 확인하고 접지를 설치합니다.","검지관이 갈색으로 변하며 청색이나 적색은 아니다":"암모니아를 검지하면 관이 갈색으로 바뀝니다.","게이지 압력은 127kPa을 초과해서는 안 된다":"아세틸렌은 압력이 높으면 분해 폭발하므로 사용 압력의 상한이 있습니다.","격리구조는 이 구조에 들지 않는다":"페일세이프의 구조에는 격리구조가 포함되지 않습니다.","격리형, 접근거부형, 위치제한형, 접근반응형":"방호장치는 위험 장소를 막는 방식에 따라 이 네 가지로 나눕니다.","경과와 결과의 보고도 포함한다":"진행 상황과 결과 보고도 계획의 일부입니다.","경영자의 자문 역할을 하며 생산부문은 안전 책임과 권한이 없다":"스태프는 조언만 하고 생산 부서에는 안전 권한이 없습니다.","경제성 평가와 작업환경 평가는 6단계가 아니다":"이 두 항목은 6단계 절차에 포함되지 않습니다.","경험 기반 행동은 분류에 없다":"라스무센의 행동 분류에는 경험 기반이라는 항목이 없습니다.","계기판 구간을 형상 부호화하고 숫자는 표시하지 않는다":"색으로 구분하기 어렵다면 모양으로 구간을 나눕니다.","계속성·계열성은 선정 원리가 아니다":"계속성과 계열성은 조직 원리입니다.","계속성 · 계열성 · 통합성의 원리":"학습경험을 짜임새 있게 조직하는 원리의 세 가지입니다.","계속성의 원리는 보기에서 제외된다":"학습지도 원리 문제에서 계속성은 정답 보기에 들지 않습니다.","고농도와 중농도용은 전면형을 사용한다":"농도가 높은 곳에서는 얼굴 전체를 덮는 전면형을 씁니다.","고도의 주의는 장시간 지속하기 어렵다":"사람은 강한 주의를 오래 유지하기 힘듭니다.","고무·합성수지 등으로 피복된 기계기구":"절연물로 싸여 있어 전기가 새도 몸에 닿지 않는 기계기구는 누전차단기가 필요하지 않습니다.","고압전로와 저압전로가 혼촉될 때의 감전·화재를 막는다":"계통접지는 전압이 다른 전선이 닿았을 때의 사고를 막습니다.","고온·고압에서 수소가 강 중의 탄소와 반응한다":"수소 취성은 높은 온도와 압력에서 수소가 강철 속 탄소와 만나 약해지는 현상입니다.","고온의 물이나 과열 수증기와 격렬히 반응한다":"마그네슘은 뜨거운 물과 반응해 수소를 냅니다.","고온이 될 우려가 있는 화기를 쓰지 않는다":"위험물이 있는 곳에서는 불씨가 될 만한 고온 화기를 쓰면 안 됩니다.","고정된 물체를 직접 분리하지 않고 하물이 안 보이면 동작하지 않는다":"붙어 있는 짐을 억지로 떼지 않고 보이지 않으면 운전하지 않습니다.","고정된 자세에서 잰 치수이다":"구조적 치수는 가만히 선 자세에서 잰 몸 치수입니다.","고체 화합물의 치사량 기호가 아니다":"MLD는 고체의 치사량 기호로 쓰이지 않습니다.","고통과 강한 근육 수축으로 호흡이 곤란하다":"이 세기의 전류는 근육이 굳어 숨쉬기가 어려워집니다.","곤돌라, 압력용기, 리프트, 프레스":"안전검사를 받아야 하는 기계 설비의 보기입니다.","곤돌라는 설치·이전 시 대상이다":"곤돌라는 설치하거나 옮길 때 안전인증을 받아야 합니다.","골절은 상해의 종류이며 발생형태가 아니다":"골절은 몸이 입은 상해의 종류이고 사고가 어떻게 일어났는지를 가리키지 않습니다.","공구를 쓰고 진동업무를 자동화한다":"진동을 줄이려면 저진동 공구를 쓰고 진동 작업을 기계로 대신합니다.","공기량으로 스프링 상수를 조절하고 측면 강성이 약하다":"공기스프링은 공기를 넣고 빼서 단단함을 조절하나 옆으로는 약합니다.","공기 중 산소 없이 자신이 분해되며 타는 것이다":"자기연소는 물질이 스스로 가진 산소로 분해되면서 타는 연소입니다.","공기 출입을 막는 밀폐는 방법이 아니다":"황린은 물속에 보관해야 하며 단순히 공기를 막는 것은 방지법이 아닙니다.","공사비를 줄이고 합성저항을 낮춘다":"공통접지는 여러 설비를 하나의 접지로 묶어 비용을 아끼고 저항을 줄입니다.","공칭지름의 7%를 넘으면 쓰지 않는다":"와이어로프가 닳아 지름이 기준보다 일정 이상 줄면 사용할 수 없습니다.","관계자 외 출입을 금하고 튼튼한 기반 위에 적재한다":"무너질 수 있는 짐더미 주변은 출입을 막고 단단한 곳에 쌓습니다.","관련 기술사 또는 3년 이상 경력의 기사, 산업안전지도사":"유해위험방지계획서 작성에 참여할 수 있는 자격입니다.","관련 법에 따른 검사원을 고용하고 있어야 한다":"자율검사프로그램을 인정받으려면 자격 있는 검사원이 있어야 합니다.","관로에 심한 맥동과 진동이 생기는 불안정 운전이다":"서징은 압축기나 펌프가 불안정하게 운전되며 압력과 유량이 출렁이는 현상입니다.","관리감독자를 대상으로 하는 기업 내 정형교육이다":"TWI는 현장 감독자를 위해 회사 안에서 정해진 틀로 하는 교육입니다.","관리감독자에 의한 안전보건 추진이다":"안전활동의 라인화는 관리감독자가 직접 안전을 챙기는 것입니다.","관리 부족이 재해의 근원적 원인이다":"제어부족은 안전 관리가 제대로 되지 않은 것을 사고의 뿌리로 봅니다.","관용평형나사로 완전나사부 5턱 이상 결합한다":"전선관은 나사를 충분히 물려 방폭 성능을 유지합니다.","관절 로봇과 극좌표 로봇은 동작 형태에 의한 분류이다":"로봇이 움직이는 모양에 따라 나뉘는 종류입니다.","관찰법은 태도조사법에 해당하지 않는다":"모랄 서베이의 태도조사법에 관찰법은 들어가지 않습니다.","광도에 비례하고 거리의 제곱에 반비례한다":"조도는 광원이 밝을수록 크고 거리가 멀수록 급히 작아집니다.","교류 1000V 이하, 직류 1500V 이하이다":"전압을 저압, 고압, 특고압으로 나눌 때 저압의 한계를 가리킵니다.","교류 1kV 초과 7kV 이하이다":"전압을 구분할 때 저압보다 높고 특고압보다 낮은 범위를 고압이라 합니다.","교류·직류 모두 7000V를 초과한다":"전압 구분에서 가장 높은 등급인 특고압의 기준입니다.","교번하중＜충격하중 순으로 커진다":"충격 하중은 가장 위험해 안전율이 가장 큽니다.","교육장소, 방법과 종류, 대상, 과목·내용":"안전교육계획에 들어갈 항목입니다.","교육 훈련은 개인 특성이 아니다":"교육 훈련은 개인 특성이 아닌 관리 요인입니다.","구부리고 양손으로 들어올리지 않는다":"허리를 굽혀 드는 자세는 허리에 부담을 줍니다.","굴착배면 상재하중 등 토압을 줄인다":"히빙은 뒤쪽 흙의 무게로 바닥이 솟는 현상이므로 그 압력을 줄여야 합니다.","굴착 저면이 솟아오르는 현상이며 주변 수위를 높이지 않는다":"히빙은 파낸 바닥이 솟는 현상이며 주변 물 높이를 올리면 오히려 위험합니다.","굴착 후 신속히 설치하고 인접 판 사이에 틈이 없게 한다":"흙이 쏟아지지 않도록 파낸 뒤 바로 설치하고 판 사이를 붙입니다.","권과방지장치, 브레이크, 클러치, 운전장치의 기능을 점검한다":"크레인 작업 전에 안전과 운전 장치를 확인합니다.","권과방지장치와 슬러스트식은 역전방지장치 형식이 아니다":"이 둘은 컨베이어 역전방지장치의 형식이 아닙니다.","귀납적으로 추리하며 복잡한 자극 형태를 식별한다":"사람은 여러 사례에서 결론을 이끌고 복잡한 자극 모양을 가려낼 수 있습니다.","귀에 불쾌한 음이나 생활을 방해하는 음을 통틀어 말한다":"소음은 듣기 싫거나 생활에 지장을 주는 소리입니다.","규모가 작은 사업장에 적용된다":"단순한 라인형은 직원이 적은 작은 사업장에 알맞습니다.","그림자가 생기지 않도록 하고 직사·반사 눈부심을 줄인다":"그림자와 눈부심은 일하는 눈을 피로하게 하므로 줄여야 합니다.","근로시간 1000시간당 2.0일이다":"강도율이 이 값이면 일한 시간 1000시간마다 근로손실일수가 이만큼 생긴다는 말입니다.","근로자 1000명당 1년간 재해발생자 수이다":"연천인율은 근로자 1000명을 기준으로 한 해의 재해자 수입니다.","근로자의 적극적 참여와 잠재 위험요인 발굴":"무재해운동의 기둥에 속하지 않는 항목으로 제시된 보기입니다.","글로우 코로나가 가장 먼저 생긴다":"정극성 코로나에서는 처음에 부드러운 빛의 글로우 코로나가 나타납니다.","금망, 소결금속, 스틸울, 다공성 금속물이다":"불꽃을 꺼뜨리는 소염소자로 쓰이는 재료입니다.","금속성 장치에 인체 일부가 상시 접촉된 상태는 25V 이하이다":"몸이 늘 닿아 있는 설비에서 허용되는 접촉전압의 상한입니다.","금속제로 내식성이 있고 폭발 압력과 온도에 견딘다":"화염방지기 본체는 녹슬지 않고 폭발 압력에 견디는 금속으로 만듭니다.","금속 증기의 응고물이 아니다":"분진은 금속 증기가 굳은 것이 아니라 고체가 부서져 생긴 가루입니다.","금형의 설계는 안전블록 사용 작업이 아니다":"금형을 설계하는 일은 안전블록을 쓰는 작업에 해당하지 않습니다.","급냉, 모재의 유황 과다, 수소·일산화탄소 과다로 생긴다":"용접부에 기포 구멍이 생기는 원인입니다.","급정지기구가 없는 프레스에 양수조작식을 쓸 수 없다":"양수조작식은 멈추는 기구가 있는 프레스에만 사용할 수 있습니다.","기계기구와 건조한 곳의 교류 150V 이하 기구도 생략한다":"이중으로 절연된 기구도 접지를 생략할 수 있습니다.","기계 수리비와 손실 시간비는 아니다":"기계 수리비 등은 간접비에 속하며 직접비가 아닙니다.","기계에 붙은 앵카 등 고정장치와 기초구조를 확인한다":"기계가 넘어지지 않게 고정 장치와 기초가 튼튼한지 봅니다.","기계 외부에 부착하지 않고 내장한다":"안전기능은 떼어 내기 쉬운 바깥이 아니라 기계 안에 넣습니다.","기계작동 중에 올라가지 않는다":"플레이너 작동 중에는 테이블 위에 올라가면 위험합니다.","기구가 간단하고 유지관리가 쉽다":"분말소화약제는 장비가 단순해 관리하기 편합니다.","기능의 이상 유무를 점검한다":"지게차 작업 전에 하역과 유압 장치가 정상으로 작동하는지 확인합니다.","기둥과 빔을 일체 구조화한다":"철골은 기둥과 보를 땅에서 미리 조립해 올려 높은 곳 작업을 줄입니다.","기온이 높을수록 커지지 않는다":"기온이 높으면 콘크리트가 빨리 굳어 측압이 커지지 않고 오히려 작아집니다.","기준을 넘으면 운전작업을 중지한다":"순간풍속이 정해진 기준을 넘으면 크레인을 멈춥니다.","긴급차단장치와 예비동력원도 필요하다":"원재료 공급 설비에는 비상시 차단하는 장치와 예비 동력이 필요합니다.","길이가 지름의 12배 이상일 때 쓴다":"가늘고 긴 가공물은 휘지 않게 방진구로 받쳐 줍니다.","깔목 등으로 각부나 가대의 침하를 막는다":"무른 땅에서는 받침목을 깔아 항타기가 가라앉지 않게 합니다.","꼬이거나 열·전기충격에 손상된 로프는 쓰지 않는다":"꼬이거나 열 손상이 있는 로프는 강도가 떨어져 쓰지 않습니다.","꼬임이 끊어진 로프는 화물운반용으로 쓰지 않는다":"섬유로프는 꼬임이 풀리면 약해져 짐을 나르는 데 쓰지 않습니다.","끈의 마모와 손상을 막아야 한다":"수인끈이 지나는 안내통이 끈을 보호해야 합니다.","끝 또는 폭에 1mm 이상 손상이 있으면 폐기한다":"안전대 벨트가 이만큼 손상되면 사용하지 않습니다.","끼우기 전에 음향검사로 균열을 확인한다":"연삭숫돌은 두드려 소리로 금이 갔는지 확인한 뒤 끼웁니다.","나일론 셔츠를 벗을 때 스파크이며 정전유도의 힘은 반발력이 아니다":"박리대전은 붙어 있던 것이 떨어지며 전기가 생기는 현상입니다.","나트륨＋물, 과산화나트륨＋염산, 염소산칼륨＋적린":"서로 섞이면 위험한 물질 조합의 보기입니다.","낙뢰로부터 전기기기를 보호하는 것이 목적이다":"피뢰 접지는 번개로부터 기기를 지킵니다.","낙뢰에 의한 피해를 방지한다":"접지는 번개에 의한 전기 피해를 막아 줍니다.","낙하물 위험이 없는 평탄한 장소에 둔다":"철골 부재는 위에서 물건이 떨어지지 않는 평평한 곳에 놓습니다.","내구성 있는 절연물로 완전히 덮어 감싼다":"충전부는 사람이 닿지 않도록 절연물로 완전히 싸야 합니다.","내면과 바닥 재질은 위험물에 내식성이 있어야 한다":"방유제 안쪽은 담긴 위험물에 부식되지 않는 재료여야 합니다.","내벽 부식, 강재의 피로, 용접 불량에서 생긴다":"용기가 압력을 견디는 힘이 모자라는 이유들입니다.","내압, 압력, 유입, 본질안전 방폭구조를 쓴다":"가연성 가스가 가끔 생기는 위험장소에서 쓸 수 있는 방폭구조의 종류입니다.","네슬러 시약으로 암모니아를 검지한다":"네슬러 시약은 암모니아와 반응해 색이 변합니다.","노출시간이 1초보다 짧을 때 광속발산도를 작게 한다는 것":"노출이 짧으면 오히려 밝게 해야 하므로 이 설명도 틀립니다.","농도 20% 염산, 50% 질산, 60% 아세트산":"부식성 산류에 해당하는 농도 기준입니다.","농약제조업(원제 제조)과 화약 및 불꽃제품 제조업":"공정안전보고서를 제출해야 하는 업종입니다.","높이 10m 이내마다 설치한다":"낙하물을 받아내는 방지망은 일정 높이마다 둡니다.","높이 5m 이상 강관틀비계에 벽이음을 설치한다":"일정 높이 이상 비계는 건물에 붙여 흔들림을 막아야 합니다.","뇌·심장·근육으로 가는 혈류가 감소하는 것도 아니다":"스트레스 때는 이 기관으로 가는 혈류가 오히려 늘어납니다.","누설전류에 의한 감전을 방지한다":"전류가 새는 설비의 전기를 땅으로 빼서 감전을 막습니다.","누전 기기에 접촉했을 때 감전 방지가 목적이다":"기기접지는 전기가 샌 기계에 닿아도 감전되지 않게 합니다.","니트로글리세린과 질산에스테르류는 금수성 물질이 아니다":"이 물질들은 폭발성 물질이므로 금수성 물질에 속하지 않습니다.","니트로화합물도 폭발성 물질이다":"니트로화합물도 폭발 위험이 커 폭발성 물질로 분류합니다.","다른 소화설비보다 우수하고 소화시간이 짧다":"분말소화약제는 불을 끄는 능력이 좋고 빨리 끕니다.","다른 시스템 프로그램 영역과 조정하며 배제하지 않는다":"다른 영역과 서로 맞추어 가며 따로 떼어 두지 않습니다.","다수에게 조직적 훈련이 가능하다":"한 번에 많은 사람을 체계적으로 가르칠 수 있습니다.","다수의 수강자를 동시에 교육할 수 있다":"한 번에 많은 사람을 가르칠 수 있습니다.","다이얼피더, 푸셔피더, 롤피더, 그리퍼피더":"프레스에 재료를 자동으로 넣어 주는 장치의 종류입니다.","다차원식 설계와 기존 제품 기준 설계":"인체측정치 응용 원칙에 들지 않는 방식들입니다.","단기간에 많은 내용을 체계적으로 전달한다":"강의법은 짧은 시간에 많은 내용을 가르칠 수 있습니다.","단락, 과부하, 절연불량, 누전이다":"전기 때문에 불이 나는 대표적인 원인입니다.","단열압축 후 온도는 T2＝T1(P2/P1)^((r-1)/r)이다":"기체를 단열 압축하면 압력비에 비례해 온도가 오릅니다.","단위 면적당 표면에 반사·방출되는 광량이다":"휘도는 면이 반사하거나 내는 빛의 양을 단위 면적당으로 나타낸 값입니다.","대기압에서 인화점 60℃ 이하이다":"인화성 액체는 낮은 온도에서도 불이 붙는 위험물입니다.","대상화학물질의 명칭·구성성분, 법적규제 현황, 폐기 시 주의사항도 있다":"자료에는 물질 이름과 성분, 규제, 폐기 시 주의가 함께 기록됩니다.","대전방지 작업복을 입고 작업대에 정전기 매트를 쓴다":"정전기 생산 장해를 줄이는 방법입니다.","대지전압 150V 이하 기계기구를 물기 없는 곳에 시설하면 제외된다":"전압이 낮고 젖지 않는 곳에 있는 기기는 누전차단기 설치 대상에서 뺍니다.","대책: 근입깊이를 깊게 하고 지하수 유입을 막는다":"말뚝을 깊이 박고 물이 들어오지 못하게 막아 보일링을 방지합니다.","덮개를 설치하고 최고사용회전수를 넘기지 않는다":"원심기는 회전체를 덮고 허용 회전수 이상으로 돌리지 않습니다.","덮개 하단이 가공재 상면에 접하는 방식이다":"가동식 접촉예방장치는 덮개가 일감 위에 닿아 톱날을 가립니다.","도괴재해와 추락재해 가능성이 크다":"가설구조물은 무너지거나 사람이 떨어질 위험이 큽니다.","도장 노후, 보온재 파손, 기초볼트 체결":"열교환기를 일상 점검할 때 눈으로 확인하는 항목입니다.","도장 열화와 기초볼트 이상 유무":"탑 설비를 일상 점검할 때 눈으로 확인하는 항목입니다.","도전성 재료를 도포하고 유속을 낮추며 대전서열이 먼 것은 피한다":"정전기를 줄이려면 전기가 통하는 재료를 바르고 서열이 먼 물질끼리 닿지 않게 합니다.","도통시험을 하고 발파기 작동상태를 확인한다":"발파 전에 전선이 이어졌는지 시험하고 발파기를 점검합니다.","독창성을 발휘하고 완전히 새로운 해결책을 찾는다":"사람은 기계와 달리 창의적으로 새로운 해법을 생각해 냅니다.","돌쌓기공과 현장타설 콘크리트 격자공":"구조물로 비탈을 보호하는 공법의 예입니다.","돌출 또는 각인으로 표시한다":"가스가 흐르는 방향을 혼동하지 않게 몸체에 새겨 둡니다.","동기, 기질, 감정, 습성, 습관이다":"안전심리를 이루는 다섯 가지 요소입니다.","동기유발 · 다목적 달성의 원리":"학습경험을 고르는 원리의 보기입니다.","동력선·조명회선과 분리해 관리한다":"점화 회선은 다른 전선과 섞이지 않게 따로 둡니다.","동시에 10명 이상 발생한 재해이다":"부상자나 직업성 질병자가 한꺼번에 많이 생긴 경우도 중대재해입니다.","동시에 2가지 이상 고장 나는 경우와 인적 원인 해석":"FMEA는 고장이 겹치는 경우와 사람 실수의 해석이 어렵습니다.","동시에 2명 이상 발생한 재해이다":"중대재해 범위에서 장기 요양이 필요한 부상자가 한 번에 여럿 생긴 경우입니다.","동시에 다수를 조직적으로 훈련하기":"O.J.T는 한 번에 많은 사람을 체계적으로 가르치기 어렵습니다.","동작시간은 0.1초 이하로 짧게, 절연저항은 5㏁ 이상이어야 한다":"누전차단기는 빠르게 동작해야 하고 절연이 충분해야 합니다.","동작 시 아크가 생기는 개폐기":"개폐 때 불꽃이 나는 기구는 가연물에서 떨어뜨려 설치합니다.","동작은 동시에 시작해 동시에 끝낸다":"양손 동작은 같은 때 시작하고 끝내도록 하는 것이 좋습니다.","될 수 있는 대로 적게 한다":"작업표준은 동작 수를 줄여 일을 단순하게 합니다.","두 개 이상의 기기고장이나 사고는 일어나지 않는다고 본다":"HAZOP은 고장이 한 번에 하나만 생긴다고 전제합니다.","두께 1.5mm 이상 철판이나 그 이상의 강도로 한다":"출입구 문은 튼튼한 철판이나 이에 맞먹는 재료로 만듭니다.","두 분포가 교차하는 곳에 있으면 Beta＝1이다":"신호와 잡음 분포가 만나는 점에 판단 기준이 있으면 베타 값은 1입니다.","둥근톱 두께의 1.1배 이상이다":"둥근톱 분할날은 톱 두께보다 약간 두꺼워야 합니다.","뒤집히거나 떨어지지 않게 하고 개구부보다 10cm 정도 크게 한다":"덮개는 고정하고 입구보다 넉넉히 커야 안전합니다.","등급별 색상을 추가 표시한다":"절연장갑은 등급마다 정해진 색으로 구분합니다.","등이 등받이에 닿도록 설계하고 몸이 큰 사람 기준이 아니다":"좌판 깊이는 작은 사람도 등을 기댈 수 있도록 맞춥니다.","뛰어내리거나 오르지 말고 안전하게 잡고 오르내린다":"불도저를 오르내릴 때는 뛰지 않고 손잡이를 잡습니다.","띠장 방향 1.85m 이하, 장선 방향 1.5m 이하이다":"비계기둥 사이 간격은 방향에 따라 이 수치 이하로 제한됩니다.","라스무센은 인간행동을 세 가지로 분류했다":"라스무센은 사람의 행동을 기술, 규칙, 지식 기반의 세 가지로 나눴습니다.","라인의 관리감독자에게도 부여된다":"안전에 대한 책임과 권한이 현장 관리감독자에게도 주어집니다.","라인형과 스태프형의 장점을 취한 절충식 조직이다":"라인-스태프형은 두 조직의 장점을 섞은 방식입니다.","램의 행정 끝과 돌출 가공물에도 덮개나 울을 설치한다":"움직이는 램 끝과 튀어나온 가공물도 막아 두어야 합니다.","렌즈 탈락·파손이 없고 취급이 간단해야 한다":"차광보호구는 렌즈가 안 빠지고 쓰기 쉬워야 합니다.","리튬 · 등유 · 황은 폭발성 물질이 아니다":"이 물질들은 폭발성 물질이 아닌 다른 위험물로 분류됩니다.","립소(rip saws)와 안전덮개":"이 둘은 반발예방장치가 아닌 톱의 종류와 덮개입니다.","마모 고장이고 조립 고장은 아니다":"설비 고장률의 기본 모형은 시간이 지나 닳아서 생기는 고장입니다.","마지막에 전동기용 개폐기를 조작한다":"마지막으로 전동기용 개폐기를 조작합니다.","마찰과 과열을 피할 수 없다":"마찰 클러치 프레스는 클러치가 마찰하므로 열이 나는 것이 피해지지 않습니다.","매끈하고 부식·흠·균열이 없어야 한다":"역화방지기의 마감 면에 결함이 있으면 가스가 새거나 불이 번질 수 있습니다.","매 반응마다 피드백이 주어져 학습자가 흥미를 갖는다":"답을 낼 때마다 결과를 알려 주어 흥미가 유지됩니다.","매슬로우의 생리적·안전·사회적 욕구와 비슷하다":"허츠버그의 위생요인은 매슬로우의 하위 욕구와 비슷합니다.","매우 불균일한 경우 유의한다":"부도체 대전이 매우 고르지 않으면 방전이 생길 수 있으니 조심해야 합니다.","매일 8시간 일해도 영향이 없는 최고 평균농도이다":"TLV-TWA는 하루 8시간 노출되어도 건강에 해가 없는 시간가중평균 농도입니다.","매일 작업 시작 전에 가스 농도를 측정한다":"지하 작업장은 매일 시작 전에 가스 농도를 확인합니다.","맥박수 · 근전도 · 산소소비량":"육체 작업의 부하를 재는 척도입니다.","메시지가 즉각적인 행동을 요구하지 않을 때":"즉시 행동할 필요가 없는 메시지는 눈으로 보는 표시가 적합합니다.","메탄올 등 안전 용제를 쓴다":"니트로셀룰로오스는 스스로 발화하기 쉬워 알코올 등에 적셔 보관합니다.","명령받는 것을 좋아한다고 본다":"X이론은 사람이 지시받는 것을 편하게 여긴다고 봅니다.","명예산업안전감독관은 사용자위원이 아니다":"명예산업안전감독관은 근로자 쪽에서 위촉하는 사람입니다.","모든 동력선은 발원점에서 15m 이상 후방으로 옮긴다":"발파 때 전기가 흘러들지 않도록 동력선을 멀리 치웁니다.","모든 명령이 생산 계통을 따라 이루어진다":"라인형 조직은 명령이 위에서 아래로 한 줄로 전달됩니다.","모든 잠재위험요인을 사전에 해결해 재해를 없애는 것이다":"무의 원칙은 사고뿐 아니라 숨은 위험 요인까지 미리 없앤다는 것입니다.","모피→유리→무명→셀룰로이드 순이다":"대전서열에서 (+)로 대전되기 쉬운 것부터 나열한 순서입니다.","목재 벽·천장으로부터 1.0m 이상이다":"고압용 아크 발생 기구는 목재 구조물에서 일정 거리 이상 둡니다.","목적결정→계획수립→활동→평가 순으로 진행한다":"구안법은 이 네 단계의 순서로 학습합니다.","목표달성을 향한 대인 간 영향력이다":"리더십은 사람들이 목표를 향해 움직이도록 영향을 미치는 힘입니다.","무게중심을 낮추고 기저를 넓혀 높인다":"몸의 안정성은 무게중심을 낮추고 발 디딘 면을 넓히면 높아집니다.","무색·무취이고 물과 급격히 접촉하면 열을 낸다":"황산은 물과 만나면 심하게 열이 나므로 조심해야 하는 부식성 물질입니다.","문제점 발견을 사실 확인보다 앞에 두지 않는다":"사례연구에서는 문제점을 찾기 전에 먼저 사실을 확인합니다.","묻힘형 부품이나 덮개 설치도 해당한다":"돌출을 없애는 묻힘형 부품이나 덮개도 외관의 안전화입니다.","물과 반응하면 수산화칼슘과 아세틸렌이 생긴다":"탄화칼슘은 물과 반응하면 불에 타기 쉬운 아세틸렌 가스를 냅니다.","물리현상을 왜곡해 지각하는 현상이다":"착각은 눈앞의 물리적 상황을 실제와 다르게 느끼는 일입니다.","물반응성 물질 및 인화성 고체이다":"황은 물과 반응하는 물질이 아니라 불에 타는 고체로 분류됩니다.","물이나 기체를 혼합하면 1m/s 이하로 한다":"물이 섞이면 정전기가 많이 생기므로 유속을 더 낮춥니다.","미끄러져 안전하고 안전장치 역할을 한다":"하중이 너무 크면 클러치가 미끄러져 기계를 보호하는 역할도 합니다.","미끄러지지 않는 구조로 한다":"가설통로가 비탈이 가파르면 발이 미끄러지지 않게 미끄럼막이를 둡니다.","미분 상태, 점화원 존재, 지연성가스 중 교반":"분진이 폭발하려면 고운 가루가 있고 불씨가 있으며 산소 속에서 섞여야 합니다.","미세한 움직임이나 변화를 표시할 때 쓴다":"동침형은 바늘이 움직여 작은 변화를 눈으로 알기 쉽습니다.","및 비상정지장치의 기능을 점검한다":"로봇의 제동과 비상정지가 제대로 되는지 확인합니다.","밑면 0.4~0.6m이고 설치위치는 조작부 중심점 기준이다":"롤러기 무릎조작식은 바닥에서의 높이와 위치 기준이 정해져 있습니다.","밑받침철물을 쓰고 수평을 유지한다":"비계기둥 아래에는 철물을 받쳐 기울지 않게 합니다.","밑변 최소폭의 4배 이하이다":"이동식비계는 높이를 폭에 비해 너무 높지 않게 제한해 넘어지지 않게 합니다.","바닥면적의 1/16 이상 단면적으로 옥상으로 돌출시킨다":"아세틸렌 발생기실의 배기통은 일정 비율 이상 단면적으로 지붕 위까지 냅니다.","바람이 불어올 우려가 있는 경우에도 한다":"강풍이 올 수 있다고 예상되면 미리 같은 조치를 합니다.","바이브로 플로테이션 · 진동다짐은 점성토 개량공법이 아니다":"이 방법들은 모래 지반을 다지는 데 쓰입니다.","바이트는 가급적 짧게 장착하고 칩은 브러시로 제거한다":"바이트를 짧게 물리면 떨림이 줄고, 칩은 손이 아닌 솔로 치웁니다.","바이트는 짧게 물리고 베드 위에 공구를 올려놓지 않는다":"바이트는 짧게 고정하고 베드에 공구를 두면 안 됩니다.","반드시 제1종을 시행하는 것은 아니다":"변압기 저압측 중성선 접지가 항상 제1종 접지공사여야 하는 것은 아닙니다.","반발경도법은 비파괴 진단법이다":"반발경도법은 콘크리트 강도를 재는 진단법이며 보강 공법이 아닙니다.","반복하중＜교번하중 순으로 커진다":"방향이 바뀌는 하중에는 더 큰 안전율이 필요합니다.","반응공정이 있으면 HAZOP을 쓴다":"화학 반응이 있는 공정은 HAZOP으로 위험을 평가합니다.","반응단계는 정보처리 3단계에 들지 않는다":"정보처리 3단계에 반응은 포함되지 않는다는 설명입니다.","반응 시 발생하는 열량이 크고 물이나 산소와 반응하기 쉽다":"위험물은 반응할 때 열을 많이 내며 물과 산소에 민감합니다.","받침대를 설치하고 아치작용이 되도록 쐐기를 박는다":"출입구 부분은 지보공이 아치처럼 힘을 받도록 쐐기로 조입니다.","받침목으로 침하를 막고 1세트 부재는 동일 평면 내에 배치한다":"기둥 밑에 받침목을 놓아 가라앉지 않게 하고 같은 평면에 놓습니다.","발산원마다 설치하고 발생원에 최대한 가깝게 한다":"후드는 오염이 나오는 곳마다 가까이 설치합니다.","발생압력은 초기압력의 20~50배이다":"아세틸렌이 폭굉하면 처음 압력보다 훨씬 높은 압력이 생깁니다.","발생 전하량 예측, 전하 축적 메커니즘 규명, 방전 조건 파악":"정전기 재해를 막으려면 전기가 얼마나 생겨 어떻게 쌓이고 언제 방전되는지 알아야 합니다.","발생한 정전기와 완화한 정전기의 차가 축적되는 현상이다":"대전은 정전기가 생기는 양이 사라지는 양보다 많아 쌓이는 현상입니다.","발열량이 크고 화염온도가 3100℃에 이른다":"아세틸렌이 분해될 때는 열이 많이 나고 불꽃 온도가 매우 높습니다.","발열반응 장치, 증류·증발 등 분리장치, 가열로이다":"특수화학설비에는 열을 내는 반응 장치와 분리 장치와 가열로가 있습니다.","발판 폭은 40cm 이상이다":"말비계가 일정 높이를 넘으면 발판 폭을 넓게 확보해야 합니다.","발화에너지가 줄고 온도에 따라 변한다":"압력이 높아지면 불이 붙기 위한 최소 에너지가 작아집니다.","발화온도에 충분한 여유가 있어야 한다":"케이블 표면 온도가 가스가 불붙는 온도보다 충분히 낮아야 합니다.","발화지연이 짧고 광분해반응이 수반될 수 있다":"혼합 위험이 있는 물질은 압력을 가하면 더 쉽게 불이 붙고 빛에 분해될 수 있습니다.","밝은 색은 상부에, 어두운 색은 하부에 둔다":"위는 밝고 아래는 어둡게 하면 안정감이 있습니다.","방사선의 성질, 필름의 종류, 현상액의 강도가 영향을 준다":"콘트라스트에 영향을 주는 조건들입니다.","방전에너지가 최소착화에너지보다 크면 일어날 수 있다":"정전기 불꽃의 에너지가 불이 붙는 최소 에너지를 넘으면 화재가 납니다.","방전하기에 충분한 전위차가 있어야 한다":"정전기가 방전되려면 전압 차이가 충분해야 합니다.","방진장갑과 귀마개를 착용한다":"진동과 소음으로부터 몸을 보호하는 보호구입니다.","방폭구조를 쓰고 내측 반경을 5배 이상으로 한다":"가요성 피팅은 방폭형으로 하고 구부림을 완만하게 합니다.","방호수단의 적정성, 주위 환경, 전기적 용량과 기계적 강도를 고려한다":"전기기계를 설치할 때 살펴볼 조건들입니다.","방호조치를 취하고 모든 설비를 등전위시킨다":"번개가 칠 때를 대비해 설비의 전위를 같게 만듭니다.","배경광 중 점멸 잡음광의 비율이 10% 이상이면 쓰지 않는다":"주변에 깜빡이는 빛이 많으면 점멸등으로 구분하기 어렵습니다.","배경소음과 다른 진동수를 쓴다":"경계 신호가 소음 속에서도 구분되도록 진동수를 달리합니다.","배관 유속을 7m/s 이하로 한다":"도전성 위험물은 흐르는 속도를 제한해 정전기 발생을 줄입니다.","밸브는 서서히 열고 용기 온도는 40℃ 이하로 유지한다":"가스 용기는 급히 열지 않고 온도가 오르지 않게 보관합니다.","버팀대 긴압 정도와 침하 정도":"흙막이 지보공을 정기 점검할 때 확인하는 부분입니다.","버팀대만으로 상단을 안정시킬 때는 3개 이상으로 한다":"버팀대로 윗부분을 고정할 때는 여러 방향에서 잡아 줍니다.","법정 교육에만 그치지 않는다":"안전교육은 법으로 정한 교육에서 멈추지 않고 필요한 것을 더 합니다.","벤튜리 미터와 피토관도 차압식이다":"이 기구들도 압력 차이로 유량을 구하는 차압식입니다.","변수는 표적 너비, 표적까지의 거리, 작업 난이도이다":"피츠의 법칙은 목표의 크기와 거리에 따라 움직이는 시간이 달라진다고 설명합니다.","병렬갭이나 충격요소로 구성되지 않는다":"병렬갭과 충격요소는 피뢰기 구성이 아닙니다.","보상은 4단계에 들지 않는다":"안전교육의 4단계에는 보상이 포함되지 않습니다.","보안경을 쓰고 면장갑을 사용하지 않는다":"선반 작업은 칩으로부터 눈을 보호하고 장갑이 말려들지 않게 합니다.","보안경을 쓰고 재질에 따라 절삭속도를 정한다":"셰이퍼 작업은 눈을 보호하고 재료에 맞는 속도로 깎습니다.","보통꼬임보다 마모 저항성이 우수하다":"랭꼬임은 같은 방향 꼬임이라 표면이 넓어 마모에 강합니다.","보통 체중의 60%가 적당하다고 할 수 없다":"운반 중량을 체중의 일정 비율로 일률적으로 정할 수 없습니다.","보호계전기를 신속히 동작시킨다":"지락 사고 때 큰 전류가 흘러 계전기가 빨리 작동하게 합니다.","보호구 착용이고 유속 가속은 아니다":"정전기를 막으려면 유속을 높이지 않고 보호구를 착용합니다.","복수방식 설치나 예비용 설비 설치 시 자물쇠형 차단밸브를 둘 수 있다":"안전밸브가 여럿이거나 예비 설비가 있으면 잠금형 밸브를 둘 수 있습니다.","복잡한 화학공정 평가에도 적절하다":"FMECA와 FTA도 복잡한 화학공정의 위험을 평가하기에 알맞습니다.","본 공사에 지장이 없도록 제거한다":"흙막이판은 공사가 끝나면 방해되지 않게 뽑아 냅니다.","본질안전 방폭구조로 0종 장소에서 쓸 수 있다":"표시 기호가 가리키는 구조는 가장 위험한 장소에서도 쓸 수 있습니다.","본질적 억제도 기본 개념이다":"점화 능력을 근본적으로 억제하는 것도 방폭의 기본 개념입니다.","부도체 중 국부적으로 도전율이 높은 곳이 대전한 경우도 유의한다":"부도체 속 전기가 잘 통하는 부분이 대전된 경우도 조심할 대상입니다.","부재의 긴압 정도, 기둥침하 유무, 접속부·교차부 상태":"터널 지보공을 점검할 때 보는 부분입니다.","분권화 · 권한위임 · 목표관리를 처방한다":"Y이론에 따라 관리자가 취하는 방식으로 권한 나눔과 목표 관리가 있습니다.","분업과 전문화로 고도의 기술을 갖는다":"집중보전은 일을 나누어 전문가가 높은 기술로 처리합니다.","분전반을 먼저 조작하거나 전동기용을 먼저 조작하지 않는다":"조작 순서를 바꾸면 위험하므로 정해진 순서를 지켜야 합니다.","분진 눈금 막힘, 실 절단, 인쇄 불량":"정전기가 생산 현장에서 일으키는 장해의 보기입니다.","분진폭발성이 있어 비산하지 않게 밀봉한다":"마그네슘 가루는 폭발할 수 있어 날리지 않게 밀봉합니다.","분할날, 반발방지기구(finger), 반발방지롤, 보조 안내판":"둥근톱에서 일감이 튕겨 나오는 것을 막는 장치입니다.","분해연소, 표면연소, 증발연소, 자기연소이다":"고체 물질이 타는 방식은 이 네 가지로 나뉩니다.","불꽃·용융금속에서 손을 보호하며 1종은 아크용접용이다":"가죽 장갑은 튀는 불꽃과 쇳물로부터 손을 지키며 종류에 따라 용도가 다릅니다.","불안전한 행위와 상태 모두에서 발생한다":"부주의는 사람의 행동과 환경 상태 양쪽에서 비롯됩니다.","불안전 행동 사고의 대부분을 차지한다":"행동에 의한 사고 중 부주의가 차지하는 비중이 큽니다.","불연성 함에 넣고 통형 퓨즈를 쓴다":"스파크가 번지지 않게 불연성 함에 담고 통형 퓨즈를 사용합니다.","불의의 이동을 막도록 갖춘다":"이동식비계는 바퀴가 저절로 구르지 않도록 제동장치를 둡니다.","브러시나 긁기봉으로 제거한다":"절삭 부스러기는 손이 아닌 도구로 치웁니다.","브레이크 장치(제동장치)도 안전장치이다":"타워크레인의 제동장치도 안전장치에 해당합니다.","비계기둥 간 400kg을 넘지 않게 한다":"비계기둥 사이에 쌓는 물건 무게는 이 한도를 넘지 못합니다.","비산으로 인한 위험을 막는다":"방호장치는 파편이 날아오는 위험도 막습니다.","비상정지장치, 가이드 레일, 브레이크, 제어장치를 본다":"승강기를 자체 검사할 때 확인하는 항목입니다.","비상정지장치, 이탈방지장치, 원동기·풀리 기능을 점검한다":"컨베이어를 쓰기 전에 안전장치와 구동부를 점검합니다.","비점이 낮은 액체 용기가 화재로 가열된다":"BLEVE는 끓는점이 낮은 액체 용기가 불에 가열되어 터지는 현상입니다.","비점화방폭구조는 기준에 들지 않는다":"비점화방폭구조는 이 위험장소에서 쓸 수 있는 구조로 인정되지 않습니다.","사고발생 확률 계산은 목표가 아니다":"PHA의 목표는 위험을 찾는 것이며 사고 확률을 계산하는 것이 아닙니다.","사고원인 규명을 간편하게 한다":"FTA로 사고 원인을 쉽게 밝힐 수 있습니다.","사고원인 분석을 일반화하고 노력과 시간을 줄인다":"FTA는 분석 방법이 정해져 있어 시간과 노력이 덜 듭니다.","사례 중심과 실연으로 기능적 이해를 돕는다":"안전교육은 사례와 직접 해 보기로 기능을 익히게 합니다.","사면 경사 증가와 굴착사면 높이 증가":"비탈이 가팔라지거나 파낸 면이 높아지면 흙이 무너지기 쉽습니다.","사무직 1년 1회와 사무직 외 6개월 1회":"일반건강진단 주기를 이렇게 정한 것은 틀립니다.","사실을 있는 그대로 수집하고 객관적·공정하게 2인 이상이 조사한다":"조사는 본 대로 모아 공정하게 여럿이 함께 해야 합니다.","사업장에 적합한 독자적 내용으로 이해하기 쉽게 구체적으로 쓴다":"안전점검표는 그 사업장 실정에 맞게 구체적으로 만듭니다.","사용수명 동안 피부자극·알레르기 등 건강상 문제를 일으키지 않아야 한다":"오래 써도 피부에 해롭지 않은 재료여야 합니다.","사용자가 뜻을 분명히 알 수 있어야 한다":"암호의 의미가 모호하지 않고 분명해야 합니다.","사용적이 작고 여과재는 여과성능이 우수해야 한다":"마스크 안의 공간은 좁고 여과재는 먼지를 잘 걸러야 합니다.","사용 전 철저히 정비·보수한다":"철골 건립 기계는 쓰기 전에 점검하고 고칩니다.","산소 농도를 측정할 사람을 지명한다":"잠함 안에서 산소가 모자랄 수 있으니 측정할 사람을 정합니다.","산업보건 및 직업병 예방, 건강증진 및 질병 예방 사항도 들어간다":"정기교육의 보건 분야 내용입니다.","산업안전 및 사고예방에 관한 사항이 들어간다":"정기교육의 안전 분야 내용입니다.","산업안전보건위원회 심의를 거친다":"공정안전보고서를 작성할 때 위원회의 심의를 받습니다.","산재보험으로 보상된 금액은 비보험 코스트가 아니다":"보험으로 지급된 금액은 비보험 코스트에서 제외됩니다.","산화나 나사풀림을 막고 비포장 퓨즈는 쓰지 않는다":"접촉이 나빠지지 않게 하고 노출된 퓨즈는 피합니다.","산화성 고체이며 염소산염류·과염소산칼륨이 해당한다":"가장 앞 번호의 위험물은 다른 물질을 산화시키는 고체입니다.","산화제와 접촉을 피하고 화기를 엄금한다":"마그네슘은 불에 잘 타므로 산화제와 불을 멀리해야 합니다.","산화프로필렌은 불활성 가스로 치환한다":"탱크로리에 주입하기 전에 불활성 가스로 공기를 바꿔 폭발을 막습니다.","삽날을 지면에 내리고 주차 제동장치를 건다":"작업이 끝나면 삽날을 내려놓고 움직이지 않게 제동합니다.","상부와 중간 난간대는 바닥면과 평행을 유지한다":"안전난간의 가로대는 기울지 않게 바닥과 나란해야 합니다.","상사와 부하의 사회적 간격이 넓고 지배적이다":"헤드십에서는 윗사람과 아랫사람 사이가 멀고 명령 중심입니다.","상시 근로자 100인 이상 사업장에 설치·운영한다":"산업안전보건위원회는 일정 규모 이상 사업장에서 두어야 합니다.","상처에 달라붙지 않은 의복은 모두 벗긴다":"전기 화상 환자의 옷은 상처에 붙은 것만 남기고 벗깁니다.","상하단 고정 · 하부 침하 방지 조치":"동바리가 움직이거나 가라앉지 않도록 위아래를 고정하고 밑을 받칩니다.","상호 신뢰와 이해도가 높아진다":"가르치는 사람과 배우는 사람이 가까워져 서로의 신뢰가 커집니다.","상황 해석이나 목표를 잘못 잡은 오류이다":"착오는 상황을 잘못 이해해 엉뚱한 목표로 행동하는 오류입니다.","생략, 실행, 시간, 순서 오류":"독립된 행동으로 구분한 휴먼에러의 종류입니다.","생산직·사무직 종사 근로자와 관리감독자이다":"정기교육은 직종별 근로자와 관리감독자를 대상으로 합니다.","생석회말뚝 공법도 점토질 개량공법이다":"생석회가 물을 흡수해 점토를 굳히므로 개량공법에 속합니다.","생존과 환경 등 동물적 욕구를 반영한다":"위생요인은 살아가는 환경에 관한 기본 욕구를 가리킵니다.","서로 다른 두 물체가 접촉한다":"접촉전위차는 서로 다른 물체가 닿을 때 생깁니다.","석분을 쓰고 마그네슘은 아니다":"분진폭발을 막는 불활성 첨가물로는 돌가루를 쓰고 마그네슘은 쓰지 않습니다.","석유 속에 저장하며 알코올 속에는 저장하지 않는다":"나트륨과 칼륨은 물과 공기를 막으려고 석유 속에 둡니다.","섞은 물을 퍼지는 상태로 방출해도 된다":"계면활성제를 섞은 물은 퍼지는 분무 형태로 쓰면 전기 화재에 쓸 수 있습니다.","선반 가공은 소성가공이 아니다":"선반 가공은 깎아 내는 절삭가공이므로 소성가공이 아닙니다.","설비 결함 개선에 쓰며 관리자 인책 자료가 아니다":"재해통계는 설비 결함을 고치는 데 쓰고 책임을 묻는 데 쓰지 않습니다.","설비 목록·사양과 안전설계 지침서도 포함한다":"설비의 종류와 사양, 안전 설계 기준도 공정안전자료에 들어갑니다.","설비 외면에서 10m 이상 둔다":"화학설비 단위공정 시설 사이에는 사고가 번지지 않도록 거리를 둡니다.","설비 이상 시 나타나는 아크이다":"단락은 전선이 합선되며 불꽃이 나는 현상입니다.","설치 볼트 직경의 2배 이상이다":"금형을 고정하는 T홈 안 볼트의 들어가는 길이 기준입니다.","설치할 때는 근로자가 쉽게 열고 닫을 수 있게 한다":"문은 작업자가 힘들이지 않고 열 수 있어야 합니다.","설치해 사람이 접촉하기 어려운 기계기구는 접지를 생략한다":"절연성 바닥 위처럼 사람이 닿기 어려운 곳에서는 접지를 하지 않아도 됩니다.","섬유에 균일하게 붙고 열 안정성이 양호하다":"대전방지제는 섬유에 고르게 묻고 열에 변하지 않아야 합니다.","성취·인정 등 자아실현 경향을 반영한다":"동기요인은 일 자체의 보람에서 오는 욕구를 가리킵니다.","세게 치지 않고 철편이 튀는 것에 주의한다":"정 작업은 처음과 끝에 무리하게 치지 않고 튀는 조각을 조심합니다.","세워서 보관하고 운반 시 캡을 씌운다":"용해아세틸렌 용기는 세워 두고 이동 때 밸브를 보호합니다.","세척처리는 침투처리 다음에 한다":"침투탐상검사는 약액을 바른 뒤에 표면 약액을 씻어 냅니다.","소선 10% 절단, 지름 7% 감소, 이음매가 있으면 쓰지 않는다":"와이어로프의 폐기 기준 세 가지입니다.","소음에 한하여 계측할 수 있는 것이 아니다":"소음계는 소음뿐 아니라 다른 소리의 크기도 측정할 수 있습니다.","소음원을 통제하고 격리하는 것이다":"소음 통제의 적극적 대책은 소리를 내는 곳 자체를 줄이거나 가두는 것입니다.","소음·진동이 항타 공법보다 낮고 시공 조인트를 잘하면 차수성이 높다":"지하연속벽은 말뚝을 박는 공법보다 조용하며 물도 막기 좋습니다.","소호리액터와 콘덴서는 피뢰기 구성요소가 아니다":"이 둘은 피뢰기를 이루는 부품이 아닙니다.","손상, 변형, 부식, 변위, 탈락 유무도 점검한다":"부재의 이상 상태를 모두 확인합니다.","송기마스크를 쓰며 방진·방독마스크는 맞지 않는다":"산소가 모자란 곳에서는 공기를 공급받는 마스크를 써야 합니다.","송기설비로 필요한 공기를 공급한다":"산소가 모자라면 공기를 보내 주는 설비를 쓰게 합니다.","쇼크를 느끼나 인체 기능에는 영향이 없다":"이 정도 전류는 짜릿하지만 몸의 기능에는 지장이 없습니다.","수명은 최소 수명 부품이 정함":"직렬계는 부품 중 가장 먼저 고장 나는 것이 전체 수명을 정합니다.","수봉식 안전기와 과부하방지장치":"이 두 장치는 공기압축기의 방호장치가 아닙니다.","수소 같은 가연성 가스가 발생한다":"위험물은 반응하면서 불에 타는 가스를 낼 수 있습니다.","수시로 점검하고 이상이 있으면 즉시 보강·보수한다":"터널 지보공은 수시로 살펴 문제가 있으면 바로 고칩니다.","수위계는 지하수위, 지중경사계는 수평 변위를 잰다":"흙막이 공사의 계측기마다 재는 대상이 다릅니다.","수인끈은 합성섬유로 지름 4mm 이상이다":"프레스 수인식 방호장치의 끈 규격입니다.","수인식과 양수조작식 방호장치는 No-hand in die가 아니다":"손을 금형 안에 넣지 않는 방식이 아니라 손으로 막아 보호하는 방식입니다.","수직 6m, 수평 8m 이내로 한다":"비계를 건물에 붙이는 벽이음의 설치 간격 기준입니다.","수직 7m·수평 9m나 수직 5m·수평 5m":"이 간격들은 기준에 맞지 않습니다.","수직방향 6m 이내, 수평방향 8m 이내마다 설치한다":"벽이음은 위아래와 좌우로 정한 간격마다 둡니다.","수직으로 넣고 간격 50cm 이하, 5~15초 둔다":"내부진동기는 곧게 꽂고 일정 간격마다 짧게 진동시켜 다집니다.","수직재와 받침철물 연결부는 받침철물 전체길이의 1/3 이상이다":"받침철물이 수직재에 충분히 겹쳐져야 힘을 전달할 수 있습니다.","수직재와 직각으로 설치하고 체결 후 흔들림이 없게 한다":"시스템비계의 수평재는 수직재에 직각으로 달고 단단히 체결합니다.","수치제어 로봇은 입력정보 교시에 의한 분류이다":"로봇을 어떻게 가르치느냐에 따른 분류에 수치제어 로봇이 있습니다.","수평면과 20° 이상 30° 이하이다":"낙하물방지망은 일정 각도로 기울여 설치합니다.","수평면에서 60° 이내로 한다":"타워크레인 지지 와이어는 수평면과 이루는 각이 기준 이내여야 합니다.","수평으로 붙인 경우 정격전류의 1.1배이다":"저압 전로의 퓨즈는 정해진 비율의 전류에서도 견딜 수 있어야 합니다.","순간풍속 10m나 20m, 25m":"이 수치들은 크레인 방호 조치의 기준 풍속이 아닙니다.","순간풍속이 초당 15m를 초과하면 운전작업을 중지한다":"바람이 이 세기를 넘으면 타워크레인 운전을 멈춥니다.","순간풍속이 초당 30m를 초과할 때 작동시킨다":"옥외 주행크레인은 바람이 매우 셀 때 미끄러지지 않게 고정 장치를 작동시킵니다.","순백색은 피하고 주위 명도의 2배 이상으로 한다":"벽은 눈부신 흰색이 아니면서 주변보다 충분히 밝아야 합니다.","순회점검, 재해통계 관리, 안전교육계획 수립":"안전관리자가 맡는 주요 업무입니다.","숫돌의 최고사용 원주속도를 넘기지 않는다":"숫돌은 정해진 가장자리 속도 이상으로 돌리면 깨질 수 있습니다.","쉽게 미끄러지지 않는 구조로 한다":"사출성형기 앞쪽 발판은 미끄럽지 않게 만듭니다.","쉽고 추간판 압력과 등근육 정적 부하를 줄인다":"의자 조절이 쉬우면 허리 디스크 압력과 등근육의 부담이 줄어듭니다.","스위프, 압력, 진공, 사이펀 퍼지가 있다":"불활성화는 설비 안 공기를 불활성 가스로 바꾸는 방법에 따라 나뉩니다.","스트랜드와 로프의 꼬임 방향이 반대이다":"보통꼬임은 가닥의 꼬임과 전체 로프의 꼬임이 반대 방향입니다.","스트리머 코로나가 먼저 나타나는 순서는 틀리다":"코로나의 진전 순서에서 스트리머를 먼저 놓은 것은 틀렸습니다.","슬라이드 하강 위험이 있는 작업에 사용한다":"프레스 슬라이드가 갑자기 내려올 위험이 있는 작업에 안전블록을 씁니다.","슬라이드 하행정거리의 3/4 위치에서 손을 밀어낸다":"손쳐내기식은 슬라이드가 내려오기 전에 손을 밀어 냅니다.","슬럼프가 크고 벽 두께가 두꺼울수록":"콘크리트가 묽고 벽이 두꺼울수록 거푸집이 받는 옆 압력이 커집니다.","슬리브 사이는 충전물로 밀폐한다":"방유제를 관통하는 배관 둘레는 틈 없이 채워 막습니다.","슬리브와 건널다리도 위험방지장치이다":"회전축을 가리는 슬리브와 건널다리도 위험 방지 장치입니다.","습기가 많은 곳에 저장하지 않는다":"습기는 자연발화를 부추기므로 습한 곳에 쌓아 두지 않습니다.","시간당 1cm 이상이면 중지한다":"눈이 많이 와서 발판이 미끄러워지면 철골 작업을 멈춥니다.","시간당 1mm 이상이면 중지한다":"시간당 1mm 이상 비가 오면 철골작업을 중지합니다.","시계가 105도 이상이고 통기성이 양호해야 한다":"고글형은 시야가 넓고 공기가 통해야 합니다.","시사를 받고 가설을 설정하고 추론하는 단계가 있다":"듀이의 사고과정은 생각이 이어지는 단계로 이루어집니다.","시선에서 멀리 두고 차양·갓·가리개를 쓴다":"눈에 직접 닿는 번쩍임을 줄이려고 광원을 시선에서 멀리 두고 가립니다.","시설을 설치할 때 그 방법이 들어간다":"환기나 조명 설비를 설치할 때의 방법도 계획에 들어갑니다.","시스템 안전의 기준 및 해석이 들어간다":"계획에는 안전 기준과 분석 방법이 포함됩니다.","시스템 안전 프로그램의 해석·검토·평가를 한다":"안전 프로그램을 분석하고 검토하며 평가합니다.","시스템이 고장 나지 않게 하는 사상의 조합이다":"최소 패스셋은 이 조합이 성립하면 시스템이 고장 나지 않는 사상의 모음입니다.","시스템 해석에 정성적·귀납적 분석법으로 쓴다":"FMEA는 부품 고장에서 출발해 시스템에 미치는 영향을 정성적으로 살핍니다.","시트파일 등의 근입심도를 깊게 한다":"흙막이 널말뚝을 깊이 박아 바닥 흙이 밀려 오르는 것을 막습니다.","시트파일 저면에서 분사현상이 일어난다":"널말뚝 아래로 물이 모래를 끌고 솟아오르는 현상입니다.","시험 단계에서 운용 안전성 분석(OSA)을 실시한다":"시스템 개발 중 시험 단계에서 운용 안전성을 분석합니다.","식별하기 어려운 표시·조종장치":"설계 단계에서 사람이 구별하기 힘들게 만든 장치가 실수를 부릅니다.","식별한 위험을 4가지 범주로 분류한다":"예비위험분석은 찾아낸 위험을 네 가지 등급으로 나눕니다.","신체 일부가 말려들 우려가 있으면 설치한다":"사출성형기에서 몸이 끼일 수 있는 곳에 양손으로 조작하는 장치를 달아야 합니다.","신호 대 배경의 휘도대비가 작을 때 백색신호가 효과적이라는 것":"경고등 설계에 대한 설명 중 틀린 보기입니다.","신호방법·화물 취급·인양물에 미치는 영향":"타워크레인 신호 작업 교육에서 다루는 내용입니다.","신호와 소음을 쉽게 식별할 수 없을 때 적용한다":"신호검출이론은 신호와 잡음을 구분하기 어려운 상황을 다룹니다.","실험실 연구와 현장 연구가 있다":"인간공학 연구는 실험실에서 하는 것과 현장에서 하는 것이 있습니다.","심신기능 · 건강상태 · 작업 부적성":"인간 실수를 일으키는 개인의 특성입니다.","심실세동에 의한 혈액순환 정지이다":"감전 사망의 가장 큰 원인은 심장이 떨기만 하고 피를 보내지 못하는 것입니다.","씰링피팅을 설치하고 씰링콤파운드로 밀봉한다":"배관이 방폭 용기로 들어가는 곳을 막아 가스가 번지지 않게 합니다.","아세틸렌 가스가 있는 곳에도 쓸 수 있다":"해당 기기는 폭발 등급이 높은 아세틸렌 가스 환경에서도 사용할 수 있습니다.","안면에 밀착되어 공기가 새지 않아야 한다":"얼굴에 꼭 맞아야 거르지 않은 공기가 들어오지 않습니다.","안전검사 기준에 충족해야 한다":"자율검사도 법정 안전검사 기준을 만족해야 합니다.","안전관리자, 보건관리자, 산업보건의, 부서의 장":"사용자 쪽 위원이 될 수 있는 사람들입니다.","안전그네만 쓰고 죔줄에 합성섬유로프를 쓸 수 있다":"추락방지대 부착 안전대는 안전그네를 쓰고 죔줄은 합성섬유로 할 수 있습니다.","안전기술 명령이 신속하지 않고 통제수속이 복잡하다":"스태프형은 지시가 현장에 빨리 전해지지 않는 단점이 있습니다.","안전난간과 미끄럼 방지 발판을 설치한다":"건널다리에는 난간과 미끄러지지 않는 바닥을 둡니다.","안전대를 착용시키고 개구부 주의 표지를 붙인다":"개구부 작업자는 안전대를 쓰고 표지로 위험을 알립니다.","안전도 증강도 기본 개념이다":"전기기기에서 안전도를 높이는 것도 방폭의 기본 개념입니다.","안전 및 보건 관리조직과 그 직무가 들어간다":"안전보건관리규정에는 조직과 맡은 일이 적힙니다.","안전밸브나 안전판을 설치한다":"배관에서 압력이 지나치게 오르면 방출되는 안전장치를 달아야 합니다.","안전밸브 전후단에는 차단밸브를 두지 않는다":"안전밸브는 항상 작동 가능해야 하므로 앞뒤에 막는 밸브를 달지 않습니다.","안전자료의 수집과 갱신이 들어간다":"시스템안전 프로그램 계획에 포함되는 항목입니다.","안전장치·보호구 사용과 기계·기구의 위험성이 들어간다":"채용 시 교육 내용에는 장비 사용법과 위험성이 있습니다.","안전장치 해지와 보호구 미착용":"불안전한 행동의 대표적인 예입니다.","안전전압의 사용과 비접지식 전로 채용":"저압 누전으로 인한 감전을 막는 그 밖의 방법입니다.","안전 정보수집이 신속하고 안전기술 축적이 쉽다":"스태프형은 안전 전문가를 두어 정보와 기술이 모이기 쉽습니다.","안전증 기호는 s가 아니고 내압 기호는 p가 아니다":"방폭구조 기호 문제에서 안전증과 내압의 기호를 서로 뒤바꾼 보기는 오답입니다.","안전표지 부착과 개폐기 투입 금지":"이 두 가지는 잔류전하 방지의 핵심 조치가 아닙니다.","안전하게 승강하는 설비를 설치한다":"작업자가 안전하게 오르내릴 설비를 마련합니다.","안전하고 경제적이며 지반성상에 맞게 선택한다":"흙막이 공법은 안전과 비용과 땅의 성질을 따져 고릅니다.","안전한 마음가짐과 가치관을 형성시킨다":"태도교육은 안전에 대한 올바른 생각과 가치관을 갖게 합니다.","안전화를 신고 안전장갑·안전모를 쓴다":"전기 작업의 감전 위험을 줄이는 개인 보호구입니다.","안전 활동과 생산업무가 분리될 우려가 낮다":"안전과 생산이 따로 놀지 않고 함께 이뤄집니다.","안전활동의 계획·조직과 관리를 포함한다":"시스템안전관리는 안전 활동을 계획하고 조직하는 일을 포함합니다.","안정기와 불안정기의 교차점이다":"위험일은 생체리듬이 좋은 시기와 나쁜 시기가 바뀌는 지점입니다.","안지름 150mm 이상 압력용기":"안전밸브는 안지름이 이 크기 이상인 압력용기에 설치해야 합니다.","암호화한 자극은 검출이 가능하고 다른 암호와 구별되어야 한다":"암호체계는 감지할 수 있고 서로 구별되어야 합니다.","압력방출장치, 드레인 밸브, 부속장치의 부식·균열":"압력용기 자체검사에서 확인하는 항목입니다.","압력방출장치와 언로드 밸브를 설치한다":"공기압축기에는 압력을 내보내는 장치와 부하를 덜어 주는 밸브를 둡니다.","압력손실이 크고 hold up이 많다":"트레이탑은 단마다 액체가 고여 있어 압력 손실이 큽니다.","압력용기에는 최고사용압력·제조연월일을 각인한다":"압력용기에는 쓸 수 있는 압력과 만든 날을 새겨 둡니다.","압력을 가하거나 진공으로 할 수 없을 때 쓴다":"스위프 퍼지는 불활성 가스를 계속 흘려보내 밀어내는 방법입니다.","압력차로 유량을 측정하며 오리피스 미터가 있다":"가변류 유량계라고 부르는 방식은 압력 차이를 이용해 유량을 잽니다.","액체가 파이프 내부를 흐를 때 관 벽과의 사이에서 생긴다":"유동대전은 액체가 관을 흐르며 벽과 마찰해 일어납니다.","액체 미립자가 아니라 금속 증기가 응고된 고체 미립자이다":"흄은 금속이 증발했다가 식어 굳은 아주 작은 알갱이입니다.","액체 화합물의 치사량 기호가 아니다":"이 기호는 기체를 들이마셨을 때 절반이 죽는 농도이지 액체의 치사량 기호가 아닙니다.","양수기동식 · 가드식 · 손쳐내기식":"급정지기구가 없어도 쓸 수 있는 방호장치입니다.","양압력이 커지고 수동토압이 줄며 뒷채움 흙무게가 늘어난다":"비가 많이 와 물이 스미면 옹벽에 불리한 방향으로 힘이 작용합니다.","어깨높이보다 높게 들지 않고 허리보다 무릎 힘으로 일어선다":"짐은 어깨 위로 들지 않고 다리 힘을 써서 일어섭니다.","어두워도 비방폭 전등을 쓰지 않고 방폭구조 전기기계를 쓴다":"밀폐공간에서는 불꽃이 나지 않는 방폭형 전기기구만 사용합니다.","언로드 밸브와 압력방출장치이다":"공기압축기의 방호장치는 압력을 줄이는 밸브와 방출 장치입니다.","없도록 설계하고 페일세이프·풀프루프 기능을 갖춘다":"본질적 안전화는 조작 때 위험이 없고 고장에도 안전하게 만드는 것입니다.","엔진 시동 전에 중립 위치에 놓는다":"불도저는 시동 걸기 전에 조종간을 중립에 둡니다.","역률개선용 커패시터가 접속된 전로는 방전에 주의한다":"커패시터는 전하를 저장하므로 방전시킨 뒤 작업합니다.","연간 재해율이 업종 평균의 2배 이상일 때도 교체한다":"재해율이 매우 높으면 안전관리자를 바꾸도록 명령할 수 있습니다.","연결볼트와 띠장으로 주재 상호간을 튼튼히 연결한다":"강아치 지보공은 주된 부재들을 볼트와 띠장으로 단단히 잇습니다.","연결 부재가 부족하고 부재 결합이 간략하여 불완전하다":"가설구조물은 연결이 부족해 약해지기 쉽습니다.","연속 변수의 대략적 값, 변화추세, 변화율을 알 때 쓴다":"정성적 표시장치는 정확한 숫자보다 대략의 값과 변화를 보일 때 씁니다.","연속 운반을 하고 직선 운반을 한다":"운반은 끊지 않고 이어서 곧은 길로 하는 것이 효율적입니다.","연쇄반응으로 진행되어 반응속도가 빠르다":"할로겐화 반응은 연쇄적으로 이어지며 빠르게 진행됩니다.","연습 · 효과 · 준비성의 법칙":"손다이크의 시행착오설이 말하는 학습의 세 법칙입니다.","연직부재 거푸집보다 빨리 떼어내지 않는다":"수평 부재 거푸집은 세로 부재보다 늦게 떼어야 합니다.","염소와 촉매 하에 반응해 포스겐이 되고 헤모글로빈과 결합한다":"일산화탄소는 반응하면 독가스가 되고 혈액에서 산소 운반을 방해합니다.","영구 일부노동 불능상해와 영구 전노동 불능상해":"이 두 가지는 일시 전노동 불능 상해가 아니라 영구적인 상해입니다.","영향을 안전한계 이내로 줄인다":"정전기가 위험하지 않은 범위로 줄여야 합니다.","예기치 못한 상황을 감지한다":"사람은 예상하지 못한 상황을 알아차리는 데 뛰어납니다.","예는 보도 표지판의 걷는 사람이다":"묘사적 부호는 실제 모습을 본뜬 그림입니다.","예는 주의를 나타내는 삼각형이다":"임의적 부호는 약속에 의해 뜻이 정해진 기호입니다.","예초기에는 날접촉 예방장치, 원심기에는 회전체 접촉 예방장치를 단다":"기계마다 몸이 닿지 않게 하는 장치가 정해져 있습니다.","오목한 곳에 두고 잠김 장치를 설치해 막는다":"우연히 작동하지 않도록 스위치를 파인 곳에 두고 잠금장치를 달아 막습니다.","온도가 올라도 인체저항은 증가하지 않는다":"전류가 흐르는 시간이 길어져 몸이 뜨거워져도 저항은 오히려 줄어듭니다.","온도계·유량계·압력계 등을 설치한다":"특수화학설비는 운전 상태를 알 수 있도록 계측 장치를 달아야 합니다.","온도와 습도가 강도에 영향을 준다":"콘크리트는 굳는 동안 주변 온도와 습도에 따라 강도가 달라집니다.","온도 차나 습도 차가 원인이 아니다":"접촉전위차는 온도나 습도의 차이 때문에 생기는 것이 아닙니다.","옷소매가 긴 작업복을 입지 않고 척에 렌치를 끼운 채 작업하지 않는다":"드릴이 소매를 말아 올릴 수 있고 렌치가 튀어 나올 수 있으므로 금지됩니다.","와이어로프가 근접하지 않게 한다":"지지 로프가 전기가 흐르는 공중 전선에 가까이 가면 안 됩니다.","와이어로프 등으로 최소 지름 8mm 이상이다":"추락방지대에 연결되는 수직구명줄의 굵기 기준입니다.","와이어로프 지지에는 전용 지지프레임을 쓴다":"타워크레인 로프를 지지할 때는 정해진 프레임을 사용해야 합니다.","외기온도 25℃ 이상에서 비비기부터 타설까지 1.5시간을 넘지 않는다":"더운 날에는 콘크리트가 빨리 굳으므로 비빈 뒤 부을 때까지 시간을 제한합니다.","외부 가스를 점화하지 않아야 한다":"용기 겉면 온도가 바깥 가스에 불을 붙일 만큼 높아서는 안 됩니다.","외부로 유출되지 않아야 한다":"내압방폭구조에서 용기 안 폭발의 화염이 밖으로 새어 나가면 안 됩니다.","외부비계·작업발판 등 가설구조물 설치비":"가설구조물 설치비는 관리비로 계상하는 비용이 아닙니다.","외부에서 내부를 볼 수 있는 구조로 한다":"방유제는 안쪽 상황을 살필 수 있게 만듭니다.","외부 충격, 측면 사용, 규정 이상 회전수":"연삭숫돌이 깨지는 대표 원인들입니다.","요소 하나만 정상이면 계가 정상":"병렬계는 부품 가운데 하나만 작동하면 전체가 정상으로 돌아갑니다.","용기 겉면의 잘 보이는 곳에 표시한다":"경고표지는 눈에 띄는 곳에 붙입니다.","용기 내 이상 압력 상승과 폭발성 혼합기 발화":"용기 속 압력이 비정상으로 오르거나 혼합 가스에 불이 붙어도 파열됩니다.","용기 온도를 40℃ 이하로 유지하고 밸브는 서서히 개폐한다":"가스 용기는 온도가 오르지 않게 하고 밸브를 천천히 엽니다.","용수 및 동결의 유무를 조사한다":"샘물이 나는지와 땅이 어는지도 확인합니다.","우수한 전문가를 강사로 활용한다":"Off.J.T는 현장 밖에서 전문가에게 배우는 교육의 장점입니다.","운반 시 10~20% 물로 젖게 한다":"피크르산은 건조하면 폭발하기 쉬워 운반할 때 물을 섞어 둡니다.","운반 작업을 집중하여 시킨다":"운반은 한 번에 몰아서 하게 하는 것이 효율적입니다.","운전·워드작업처럼 부위가 조화를 이루며 움직일 때의 치수이다":"기능적 치수는 동작을 하는 중에 측정한 몸 치수입니다.","움직일 때는 되도록 중력을 이용한다":"재료를 옮길 때 중력으로 힘을 덜 쓰도록 합니다.","워크레스트와 조정편을 설치한다":"탁상용 연삭기는 일감을 받치는 대와 틈을 조절하는 부품을 둡니다.","원동기, 회전축, 기어, 풀리, 플라이휠, 벨트에 설치한다":"회전하는 동력 전달 부위에 덮개를 씌웁니다.","원심기가 아니라 압력용기에 설치한다":"압력방출장치는 압력용기용이며 원심기에는 달지 않습니다.","원인·결함 규명, 예방 자료수집, 동종·유사재해 재발방지":"재해를 조사하는 목적은 원인을 밝히고 예방 자료를 모으며 재발을 막는 것입니다.","원인은 두 물체의 일함수 차이다":"물질마다 전자를 놓는 데 필요한 에너지가 달라 전위차가 생깁니다.","원주속도가 초당 120m 이상이다":"고속회전체 검사 대상은 가장자리 속도가 매우 빠른 회전체입니다.","원주의 1/2.5 이내에서 정지한다":"롤러가 빠르면 그에 맞춰 정지 허용 거리가 달라집니다.","원주의 1/3 이내에서 정지한다":"롤러 속도가 느린 경우 급정지 시 롤러가 돈 거리 한도를 정한 기준입니다.","원칙적으로 금지하고 주위에 관계자 외 출입을 금한다":"위아래에서 동시에 작업하면 위험하여 막고 주변 출입도 제한합니다.","원활한 작동을 위한 급유는 아니다":"기름칠은 기능 안전화의 적극적 대책에 해당하지 않습니다.","위의 저압용 기계기구와 절연대 설치 기구도 생략한다":"마른 나무 바닥 위의 낮은 전압 기구나 절연대 위의 기구도 접지가 필요 없습니다.","위팔을 수직으로 늘어뜨리고 아래팔만으로 뻗는 구역이다":"정상작업역은 어깨를 움직이지 않고 팔꿈치 아래로 닿는 범위입니다.","위험물 건조설비는 직화를 쓰지 않는다":"위험물을 말릴 때는 불꽃이 직접 닿는 방식을 피합니다.","위험 부분에는 안전하게 작업할 조명을 유지한다":"화물 작업장은 어두운 위험 구역에 충분한 조명이 있어야 합니다.","위험부위와 신체의 접촉을 막는다":"방호장치는 몸이 위험한 부분에 닿지 않게 합니다.","위험성 감소대책, 하도급 사업장 관리, 질병자 근로 금지도 들어간다":"위험을 줄이는 방법과 하도급 관리, 질병이 있는 근로자의 근로 금지도 규정 내용입니다.","위험한 톱날 부위에는 덮개를 설치한다":"띠톱 기계는 사람이 닿지 않게 톱날을 가립니다.","유기물의 불완전연소로 생긴 미립자이다":"스모크는 물질이 덜 타면서 생긴 작은 입자입니다.","유도자 배치 사항은 포함되지 않는다":"이 작업계획서 포함 항목에 유도자 배치는 들어 있지 않습니다.","유체 온도차를 크게 하고 열전도율이 높은 재료를 쓰면 오른다":"열교환기는 온도 차가 크고 열을 잘 전하는 재료일수록 효율이 좋아집니다.","유해물의 위치나 작업공정을 변경한다":"유해물 노출을 줄이려면 물질의 위치나 작업 방식을 바꿉니다.","유해물질 흡인에 적당하게 하고 포위식·부스식이 좋다":"후드 형식은 유해물질을 잘 빨아들일 수 있는 포위식이나 부스식이 좋습니다.","유해·위험물질의 물질안전보건자료도 포함한다":"공정안전자료에는 취급하는 위험 물질의 정보 자료도 들어갑니다.","유해·위험 작업환경 관리도 포함한다":"위험한 작업환경을 관리하는 방법도 교육 내용입니다.","유해인자 노출기준을 초과한 사업장이다":"유해인자 노출이 기준을 넘으면 안전보건개선계획 수립 대상입니다.","육체작업 부하 척도는 아니다":"점멸융합주파수는 정신적 피로를 재는 척도입니다.","윤활유 상태, 회전부 덮개·울, 압력용기 외관을 점검한다":"공기압축기를 가동하기 전에 살피는 항목들입니다.","의도는 맞으나 행동이 다르게 나타난 오류이다":"실수는 하려던 것은 옳은데 동작이 어긋난 것입니다.","의미를 알도록 질서 있게 가르친다":"이해할 수 있게 순서를 갖추어 가르치면 잘 잊히지 않습니다.","의사 진단으로 일정 기간 정규 노동을 못 하는 상해이다":"일시 전노동 불능은 치료 중 일정 기간 일을 할 수 없는 상해입니다.","의식과잉, 주변 영향, 피로·과로":"작업자가 안전 수단을 생략하게 만드는 심리적 요인입니다.","이동하지 않게 가대에 견고히 부착한다":"평형추가 움직이면 균형이 깨지므로 단단히 붙여 둡니다.","이상을 확인하고 급정지시키는 것이다":"소극적 대책은 이상이 생기면 멈추게 하는 방법입니다.","이으면 4개 이상 볼트로 결속":"서포트를 이어 쓸 때는 볼트 네 개 이상으로 단단히 묶습니다.","이음매가 있거나 심하게 변형·부식·열손상된 로프는 쓰지 않는다":"로프의 이음매와 손상은 강도 저하를 뜻하므로 쓰지 않습니다.","이음매가 있으면 쓰지 않는다":"와이어로프는 이어 붙인 부분이 약하므로 이음매가 있으면 쓰지 않습니다.","이황화탄소의 하한계가 가장 작다":"폭발하한계가 낮을수록 적은 양으로도 폭발하므로 이황화탄소가 가장 위험합니다.","익숙해지기 쉽고 피해는 정신적·심리적인 것이 주가 된다":"소음에는 적응이 되며 피해는 주로 마음에 나타납니다.","인간의 기대가 자극·반응과 모순되지 않는 관계이다":"양립성은 사람이 예상하는 방향과 장치의 반응이 서로 어긋나지 않는 성질입니다.","인간의 성과×물질의 성과＝경영의 성과":"데이비스는 사람의 능력과 동기를 곱한 값으로 성과를 설명했습니다.","인간의 제어행동을 수식화한 모델이다":"인간 전달함수는 사람의 조작 행동을 식으로 나타낸 모형입니다.","인간이 본래 게으르다고 본다":"X이론은 사람이 본래 일하기를 싫어한다고 가정합니다.","인간이 조건에 따라 자발적으로 책임지려 한다":"Y이론은 사람이 환경이 맞으면 스스로 책임지고 일한다고 봅니다.","인체 및 환경에 미치는 영향, 취급주의 사항이 있다":"물질안전보건자료에 적히는 항목입니다.","인체 및 환경에 미치는 영향을 기입한다":"사람과 환경에 미치는 영향을 적어 알립니다.","인화성 가스 농도 상승을 조기에 파악하려는 장치이다":"터널 자동경보장치는 가스 농도가 오르는 것을 일찍 알려 줍니다.","인화성 물체 사이에는 안전거리를 둔다":"가열로와 불에 붙기 쉬운 물질 사이에는 거리를 둡니다.","인화성 액체 개방 저장조와 유압 조작기계 등에 쓴다":"물분무 소화설비는 인화성 액체나 기름 쓰는 기계의 불을 끄는 데 쓰입니다.","인화점 60℃ 이하가 해당한다":"인화성 액체는 인화점이 낮아 쉽게 불이 붙습니다.","일관성 · 계속성 · 강도의 원리":"조건반사설에서 학습이 일어나게 하는 원리입니다.","일반적으로 각 취관마다 안전기를 설치한다":"아세틸렌 용접장치는 불꽃이 거꾸로 가지 않도록 토치마다 안전기를 둡니다.","일산화탄소가 질식을 일으킨다":"일산화탄소는 독성 가스로 높은 농도에서 질식을 일으킵니다.","임명된 헤드가 갖고 근거는 공식적이다":"헤드십의 권한은 지위에서 나오며 임명으로 주어집니다.","입력의 협소성, 시점적 제약성, 불충분한 직무 묘사":"인간 전달함수 모델의 단점들입니다.","입술·피부 색깔, 체온, 전기출입부 상태도 살핀다":"감전된 사람의 몸 상태를 관찰합니다.","입자 상호간이나 입자와 고체의 충돌로 생긴다":"충돌대전은 입자들이 부딪칠 때 전기가 생기는 현상입니다.","자극이 강한 색은 피하고 차분하고 밝은 색을 고른다":"작업장 색은 눈이 피로하지 않게 부드럽고 밝은 색이 좋습니다.","자기반응성이며 니트로글리세린은 제3류가 아니라 제5류이다":"제5류는 스스로 분해해 폭발하는 물질이며 니트로글리세린이 속합니다.","자동제어 관련 설비와 가스누출 감지·경보설비":"화학설비의 부속설비에는 제어와 감지 설비가 포함됩니다.","자동화될수록 경계·감시·보전 업무가 늘어난다":"자동체계에서 사람은 직접 조작보다 감시와 점검 역할이 커집니다.","자동화라인의 출입시스템과 리프트의 출입문 안전장치도 해당한다":"인터록은 위험한 상태에서는 문이 열리지 않게 하는 장치입니다.","자외선용, 적외선용, 복합용, 용접용이 있다":"차광용 보안경은 막는 빛의 종류에 따라 나뉩니다.","작동의 이상 유무를 점검한다":"로봇 교시 작업 전에 팔 부분이 정상으로 움직이는지 살핍니다.","작업 개시 전 점검과 물질안전보건자료에 관한 사항도 포함한다":"시작 전 점검과 물질 정보 자료 교육도 포함됩니다.","작업공정을 은폐하고 작업장을 격리하며 환기·대치·교육을 한다":"공정을 가리고 작업장을 따로 두며 환기와 대체와 교육으로 예방합니다.","작업내용 변경자와 위험작업 종사자이고 계절 작업자도 포함된다":"채용 시 교육은 신규뿐 아니라 일이 바뀐 사람과 계절 근로자도 받습니다.","작업면 조도는 300럭스 이상이다":"정밀작업의 작업면 조도는 300럭스 이상이어야 합니다.","작업발판을 설치하며 폭은 40cm 이상이다":"높은 곳 비계에는 작업발판을 일정 폭 이상으로 깔아야 안전합니다.","작업 시작 전 1분 이상, 숫돌 교체 후 3분 이상 한다":"연삭기는 시운전으로 이상 여부를 확인한 뒤 작업합니다.","작업시작 전 계기, 검지부, 경보장치 작동상태를 점검한다":"작업 전에 장치가 제대로 작동하는지 확인합니다.","작업의 흐름에 따라 배치한다":"작업장의 기계는 일이 진행되는 순서대로 놓아 동선을 줄입니다.","작업장 안전 및 보건관리, 사고 조사 및 대책 수립도 들어간다":"작업장 관리와 사고 조사 방법도 규정에 포함됩니다.","작업장 용도와 특성에 맞게 한다":"출입구의 위치와 개수와 크기는 작업장 성격에 맞춰 정합니다.","작업 전과 작업 중 충분히 환기하고 입퇴장 시 인원을 점검한다":"맨홀에서는 환기를 하고 들어간 사람 수를 확인합니다.","작업환경 관리, 표준안전작업방법, 재해 예방대책":"관리감독자 정기교육에서 다루는 주요 내용입니다.","작은 분출구로 분출될 때 생긴다":"분출대전은 좁은 구멍으로 물질이 뿜어 나올 때 생깁니다.","잠재위험 요인을 사전에 파악해 뿌리에서부터 없애는 것이다":"무의 원칙은 숨은 위험까지 미리 찾아 없애는 것입니다.","잠함·잠수작업 등은 1일 6시간으로 제한한다":"높은 압력에서 일하는 시간은 하루 6시간 이내입니다.","장갑·반지를 착용하지 않고 보링 중에는 칩을 제거하지 않는다":"회전하는 선반에 말려들 수 있는 물건을 피하고 작업 중에는 칩을 치우지 않습니다.","장갑을 쓰지 않고 보호안경을 반드시 쓴다":"가공 중에는 장갑이 말려들지 않게 벗고 눈을 보호합니다.","장례비 · 치료비 · 요양비":"직접비는 재해 때문에 바로 지출하는 보상 비용입니다.","장애물 뒤 타겟과의 거리를 확보하는 설계이다":"접근제한요건은 장애물 때문에 대상에 닿기 어려운 거리를 고려한 설계입니다.","장치는 설계·제작사양대로 제작됐다고 본다":"HAZOP은 설비가 설계대로 만들어졌다고 전제합니다.","재료 선택, 설계 시 강도계산, 가공 상의 안전화":"구조적 안전화는 재료와 설계와 가공 단계에서 안전을 확보하는 것입니다.","재해를 예방할 안전대책은 반드시 존재한다":"사고의 원인을 알면 예방할 방법이 반드시 있다는 원칙입니다.","재해를 정량적으로 예측할 수 있다":"FTA로 재해 확률을 수치로 계산해 예측할 수 있습니다.","재해 발생과 손실의 발생은 우연적이다":"같은 사고도 결과로 나타나는 손실의 크기는 우연히 정해집니다.","재해상황 파악이 먼저이고 사실 확인이 다음이다":"재해사례연구는 상황을 파악한 뒤 사실을 확인하는 순서입니다.","재해에는 반드시 원인이 존재한다":"재해예방 원칙 중 사고에는 반드시 원인이 있다는 원인 계기의 원칙입니다.","재해 원인들을 Tree로 표현한다":"FTA는 원인과 결과를 나뭇가지 모양으로 그려 나타냅니다.","재해율이 업종 평균의 2배 이상이거나 중대재해가 발생한 사업장도 대상이다":"재해가 많거나 큰 사고가 난 사업장도 개선계획을 세워야 합니다.","재해조사 단계에서 잠재재해 위험요인을 색출한다":"사고를 조사하면서 아직 드러나지 않은 위험 요인도 찾아냅니다.","재해 확률의 목표치를 정한다":"FTA에서 정상사상의 발생 확률 목표를 설정할 수 있습니다.","저장소 사이에 안전기를 두고 아세틸렌 밸브를 먼저 연다":"분리된 장치 사이에 안전기를 놓고 가스 밸브를 먼저 엽니다.","적당한 조명으로 기분을 좋게 하고 광속발산도 분포를 고르게 한다":"좋은 조명은 쾌적하고 밝기 차이가 크지 않습니다.","적절한 지도계획을 세우고 연습한다":"망각을 줄이려면 계획에 따라 지도하고 반복해 연습시킵니다.","전 공장 판단으로 중점보전을 수행한다":"집중보전은 공장 전체를 보고 중요한 곳부터 보전합니다.","전기기기의 종류, 전기배선 방법, 방폭구조의 종류":"방폭설비를 고를 때 고려해야 할 사항입니다.","전기화재이며 금속화재는 C급이 아니다":"C급 화재는 전기가 원인인 불이고 금속이 타는 불은 D급입니다.","전노동불능(1~3급)은 7500일로 환산한다":"사망과 영구 전노동불능은 근로손실일수를 7500일로 계산합니다.","전동기 운전 시 메인 스위치부터 조작한다":"전동기를 켤 때는 큰 스위치부터 차례로 넣습니다.","전로의 충전 여부는 검전기로 시험한다":"전기가 흐르는지는 검전기로 확인합니다.","전류는 전압을 저항으로 나눈 값이다":"옴의 법칙에 따라 몸에 흐르는 전류는 전압을 저항으로 나누어 구합니다.","전류 용량은 부하전류 이상이고 부동작전류는 감도전류의 50% 이상이다":"정격 선택 시 부하를 견디고 오작동하지 않을 기준을 지켜야 합니다.","전문성을 크게 요구하지 않고 팀 단위 수행이 가능하다":"HAZOP은 여러 사람이 팀으로 수행하며 전문 지식 부담이 적습니다.","전선로를 개로한 후에도 잔류전하가 남을 수 있다":"전력케이블은 전류를 끊어도 전기가 남아 있을 수 있습니다.","전신자각 증상은 생리적 방법 검사항목이 아니다":"전신자각 증상은 심리적 방법으로 파악하는 항목입니다.","전열면 증발률이 커지고 효율이 낮아진다":"보일러 부하가 지나치면 열을 받는 면에서 증발이 과해지고 효율이 떨어집니다.","전원이 참가해 의욕적으로 문제해결을 실천하는 것이다":"참가의 원칙은 모두가 함께 문제 해결에 나서는 것입니다.","전원이 협력해 문제해결 운동을 하는 것이다":"참가의 원칙은 모든 사람이 함께 문제를 해결한다는 것입니다.","전원 쪽을 먼저 연결하지 않는다":"전선을 이을 때는 전원 쪽부터 연결하면 위험합니다.","전조등, 후미등, 방향지시기, 경보장치를 점검한다":"지게차의 등과 경보 장치를 점검합니다.","전처리 다음에 세척처리를 먼저 하지 않는다":"전처리 뒤에는 침투 처리를 먼저 해야 합니다.","전체 전망을 제시하는 데 유리하다":"강의법은 전체의 흐름을 설명하기에 알맞습니다.","절단공법이 있고 진공공법은 아니다":"건축물 해체 공법에 진공공법은 포함되지 않습니다.","절연방호구를 쓰고 전로를 절연한다":"노출된 충전부는 절연 덮개를 씌우고 전선을 절연합니다.","절연 장갑과 절연 용접봉 홀더를 쓴다":"아크용접 감전을 막으려면 전기가 통하지 않는 장갑과 홀더를 씁니다.","점검이 쉬운 옥외 인입선의 부하측에 설치한다":"누전경보기 변류기는 점검하기 쉬운 옥외 인입선 부하 쪽에 둡니다.","접속부·교차부와 손상·변형·부식·변위·탈락을 점검한다":"부재가 연결된 곳과 부재 자체의 이상을 살핍니다.","접지극의 매설 깊이를 증가시킨다":"접지극을 깊이 묻으면 저항이 줄어듭니다.","접지시설 · 누전차단기 · 고압전선보호시설":"산업안전보건관리비로 쓸 수 있는 전기 안전 비용의 보기입니다.","접지저항은 10Ω 이하가 아니다":"접지공사의 종류별 접지저항 기준은 같은 값으로 단정할 수 없습니다.","접지하고 유체 종류별로 색을 구별한다":"폭발 가능한 유체를 나르는 배관은 접지하고 유체별로 색을 달리해 구분합니다.","접촉면적과 인가전압에 따라 변한다":"인체 저항은 닿는 면적과 걸리는 전압에 따라 달라집니다.","접촉면적이 크고 접촉압력이 높을수록":"정전기는 두 물체가 많이 닿고 세게 눌릴수록 더 많이 생깁니다.","정격전류의 1.25배가 아니다":"비포장 퓨즈의 기준은 정격전류의 1.25배가 아닙니다.","정격 하중·운전 속도·경고 표시를 보기 쉬운 곳에 표시한다":"양중기에는 하중과 속도와 경고를 잘 보이게 적어 둡니다.","정기, 수시, 특별, 임시점검으로 나뉜다":"안전점검은 시기와 목적에 따라 이렇게 구분합니다.","정기적으로 검토하며 위험성이 낮은 순서로 작성하지 않는다":"점검표는 때때로 고치고 위험이 큰 순서를 중시합니다.","정보가 일정시간 뒤 재참조될 때":"시각장치는 정보를 나중에 다시 볼 필요가 있을 때 알맞습니다.","정보 전달에 유리하며 단일 차원 암호가 더 낫지 않다":"여러 차원을 쓰는 암호가 정보를 더 잘 전달합니다.","정상동작 표시램프는 녹색, 위험표시램프는 적색으로 한다":"광전자식 방호장치는 상태를 색으로 구분해 보입니다.","정상사상을 일으키는 최소한의 컷셋이다":"최소 컷셋은 정상사상을 일으키는 데 꼭 필요한 기본사상의 최소 조합입니다.","정 작업에는 반드시 사용한다":"정으로 쪼는 작업에는 파편으로부터 눈을 지키는 보안경이 필요합니다.","정전기방지 작업복을 입고 유지 부착 작업복은 입지 않는다":"기름이 묻은 옷은 불이 붙기 쉬우므로 피합니다.","정하중＜반복하중 순으로 커진다":"하중이 반복될수록 재료가 지치므로 안전율을 더 크게 잡습니다.","정해진 스위치를 쓰고 운전 전 주변에 경고한다":"이동식 컨베이어는 지정된 스위치로 켜고 주변에 알립니다.","정확하고 견고하게 되도록 짧게 장치한다":"절삭 작업에서 바이트는 짧고 단단히 고정합니다.","정확한 값을 읽을 때는 아날로그가 아니라 디지털이 유리하다":"정밀한 수치는 숫자로 직접 보이는 디지털 표시가 낫습니다.","제거한 뒤 모래 등으로 잘 메운다":"널말뚝을 뺀 구멍은 모래로 채웁니다.","제시: 내용을 이해시키고 납득시키는 단계":"안전교육의 단계 중 제시는 가르칠 내용을 이해하고 수긍하게 하는 단계입니다.","제전기를 쓰고 화학섬유 작업복은 입지 않는다":"전기를 없애는 장치를 쓰고 정전기가 잘 생기는 옷을 피합니다.","제전능력이 작지 않고 코로나 방전으로 공기를 이온화한다":"자기방전식은 코로나 방전으로 공기를 이온으로 만들어 정전기를 없앱니다.","제전복 착용과 제전용구 사용을 한다":"사람 몸에 쌓인 정전기를 막으려면 제전복을 입고 제전 도구를 씁니다.","제조 때보다 5% 넘게 늘면 폐기한다":"달기체인이 늘어나면 약해진 것이므로 일정 이상 늘면 폐기합니다.","제조번호 및 제조연월을 표시한다":"자율안전확인 제품은 만든 번호와 시기를 표시해야 합니다.","조립 정밀도가 낮고 과소단면이거나 결함재가 되기 쉽다":"가설구조물은 만들 때 정밀하지 않고 부재가 약할 수 있습니다.","조립 해체 시 사고 예방과 조립방법·설치기준":"거푸집 동바리 작업에 관한 교육 내용입니다.","조작이 편하고 습기에 노출되지 않으며 정비 공간이 있는 곳":"방폭설비는 다루기 쉽고 젖지 않으며 정비할 공간이 있는 곳에 설치합니다.","조작자는 위험상황을 인식할 수 있다고 본다":"HAZOP은 작업자가 위험을 알아차린다고 가정합니다.","종이·목재·섬유류 화재, 일반화재이다":"A급 화재는 종이와 나무, 섬유가 타는 일반적인 화재입니다.","좋고 경제적이며 보수가 쉬워야 한다":"조명은 보기 좋고 비용이 적게 들며 관리하기 쉬워야 합니다.","좌측에서 우측으로 화살표를 긋는다":"특성요인도의 등뼈는 왼쪽에서 오른쪽으로 화살표를 그려 결과를 가리킵니다.","주관 및 분기관에 안전기를 설치한다":"가스집합 용접장치는 큰 관과 갈라지는 관에 안전기를 설치합니다.","주로 고음을 차음하고 저음은 차음하지 않는 기호이다":"이 기호의 귀마개는 높은 소리를 주로 막고 낮은 소리는 막지 않습니다.","주목적이어도 보행자용 출입구를 따로 설치한다":"짐을 나르는 출입구가 있어도 사람이 다니는 문을 따로 둡니다.","주위온도 -20~40℃이고 산소 함유율은 21%이다":"방폭기기가 시험된 표준 환경 조건입니다.","주위 환경 간섭을 덜 받고 참가자 안전 확보가 쉽다":"실험실은 외부 영향이 적고 참여자를 안전하게 지킬 수 있습니다.","주틀 간격은 1.8m 이하로 한다":"비계가 높으면 주틀 사이 간격을 좁게 합니다.","주행로 상측과 트롤리 횡행 레일 상태를 점검한다":"크레인이 다니는 레일에 이상이 없는지 살핍니다.","준비, 교시, 연합, 총괄, 응용":"하버드학파가 정리한 교수법의 다섯 단계입니다.","중대재해 연 3건 이상 등이다":"안전관리자를 교체해야 하는 사유의 보기입니다.","중크롬산과 과산화수소도 산화성 물질이다":"이 물질들도 산소를 내어 다른 물질을 태우는 산화성 물질입니다.","쥐, 4시간 흡입 2500ppm 이하인 물질이다":"가스를 4시간 흡입시켜 절반이 죽는 농도가 이 이하면 급성독성입니다.","즉시 발파모선을 발파기에서 분리하고 단부를 절연시킨다":"발파가 끝나면 전선을 떼어 내고 끝을 절연해 오작동을 막습니다.","증기를 대기로 방출하는 설비의 상단에 설치한다":"증기가 나가는 설비의 위쪽에 화염방지기를 둡니다.","증기폭발은 기상폭발이 아니다":"증기폭발은 액체가 급히 기화하는 현상이라 응상폭발로 분류됩니다.","지락보호용은 과전류 차단기와 조합해 접속한다":"누전차단기는 과전류를 막는 차단기와 함께 연결합니다.","지락에 의한 아크와 차단기에서의 아크도 해당한다":"땅으로 전기가 샐 때와 차단기가 끊을 때의 불꽃도 아크 종류입니다.","지름 2.7cm 이상의 금속 파이프이다":"난간대는 일정 굵기 이상의 금속관 재질이어야 합니다.","지름 50mm 이상 이물질 보호이다":"IP 등급 첫째 자리 숫자가 가장 낮은 단계로 큰 이물질만 막는 정도입니다.","지름 60mm 이상 평형플랜지":"이 크기 숫돌에는 지름 기준 이상인 평평한 고정판을 써야 숫돌이 흔들리지 않습니다.","지름이 아니라 원주 기준이다":"급정지거리는 롤러 지름이 아닌 원둘레 길이를 기준으로 정합니다.","지반공학적 조건, 표준관입시험치와 콘관입저항치 분석이 들어간다":"조사 보고서에 담기는 분석 내용입니다.","지반지지력에 대해 안정해야 한다":"옹벽은 땅이 받쳐 줄 수 있는 힘 안에서 안정해야 합니다.","지상 1층(6m 초과 시 6m)까지 내화구조로 한다":"폭발 위험 장소의 건물 기둥은 아랫부분을 불에 견디게 만듭니다.","지상에서 지지대 끝부분까지 내화구조로 한다":"위험물 용기를 받치는 지지대는 끝까지 불에 견디게 합니다.","지상으로부터 1단(6m 이내)까지 내화구조로 한다":"배관 지지대는 지상에서 일정 높이까지 내화구조로 합니다.","지주부재와 수평면의 기울기는 75° 이하로 한다":"말비계 지주부재와 수평면 사이 기울기는 75° 이하로 합니다.","지중전선로와 가공전선로가 접속되는 곳에 설치한다":"땅속 전선과 공중 전선이 이어지는 곳에 피뢰기를 설치합니다.","지질 및 지층의 상태를 조사한다":"굴착 전에 땅의 종류와 층 상태를 확인합니다.","지층상태와 구조물 규모에 따라 정하고 지층이 복잡하면 보완조사를 한다":"조사 간격은 땅과 구조물에 맞게 정하고 복잡하면 더 조사합니다.","지하매설물을 조사하고 조립도를 작성해 작업순서를 지킨다":"흙막이 지보공은 땅속 시설을 확인하고 조립도에 따라 순서대로 설치합니다.","지하수위가 높은 연약 사질토 지반 굴착":"보일링은 지하수가 높은 무른 모래땅을 파낼 때 생깁니다.","지하수위 증가와 점착력 감소":"땅속 물이 늘고 흙의 붙는 힘이 약해지면 토사가 붕괴합니다.","직렬갭과 특성요소로 구성된다":"밸브저항형 피뢰기는 방전을 시작하는 간격과 저항 요소로 이루어집니다.","직장 실정에 맞는 실제적 교육":"O.J.T는 일하는 현장에서 실제로 하는 교육입니다.","직장 실정에 맞는 실제적 훈련":"실제 직장 업무와 맞는 훈련이 가능합니다.","직종 간 연락이 좋고 공사 관리가 쉽다":"한곳에서 모이므로 직종 사이의 소통과 공사 관리가 쉽습니다.","진동방지장갑과 청력보호구, 마스크를 착용하고 쓴다":"진동 공구를 쓸 때 몸을 보호하는 보호구입니다.","진행방향을 향하고 뒷걸음 운반을 하지 않는다":"사람이 짐을 나를 때는 앞을 보고 걷습니다.","질산에스테르는 산화성 액체·고체가 아니다":"질산에스테르는 스스로 폭발하는 폭발성 물질로 분류됩니다.","질산에스테르류와 유기과산화물은 폭발성 물질이다":"스스로 분해해 폭발하기 쉬운 물질입니다.","질산 · 염소산 · 과염소산 및 그 염류":"다른 물질을 산화시켜 타게 하는 산화성 액체와 고체입니다.","집단 내에 머물도록 하는 내부의 힘이다":"응집력은 구성원이 그 집단에 남게 하는 힘입니다.","집단 유지와 목표 달성을 위해 만들어지며 변화할 수 있다":"규범은 집단이 지켜야 할 행동 기준으로 필요에 따라 바뀝니다.","짧게 설치하고 칩이 길게 되도록 칩 브레이커를 쓰지 않는다":"바이트를 짧게 달고 칩이 짧게 끊기도록 칩 브레이커를 씁니다.","짧게 하고 굴곡부를 줄이며 개구부 면적을 크게 하지 않는다":"덕트는 저항이 작도록 짧고 곧게 합니다.","차단기의 차단 여부를 확인한 후 개폐한다":"단로기를 만지기 전에 차단기가 꺼졌는지 먼저 확인합니다.","차륜을 고정하고 하물을 올린 채 반복 시동하지 않는다":"바퀴를 고정하고 짐을 얹은 채로 자꾸 켜지 않습니다.","착각이나 의식의 우회에 기인한다":"부주의는 상황을 잘못 받아들이거나 의식이 딴 데로 쏠려서 생깁니다.","착용자에게 물리적 손상을 주지 않고 사용 중 쉽게 빠지지 않아야 한다":"귀마개는 귀를 다치게 하지 않고 단단히 끼워져야 합니다.","참모식보다 경제적이며 안전 전담요원을 따로 두지 않는다":"라인형은 별도 안전 전담 인력을 두지 않아 비용이 적게 듭니다.","처음 접촉·분리할 때 발생량이 최대이다":"정전기는 처음 닿았다 떨어질 때 가장 많이 생기고 반복하면 줄어듭니다.","철과 반응하는 현상이 아니다":"수소 취성은 수소가 철 자체와 반응하는 것이 아닙니다.","철저히 점검하고 필요한 부분에 보호접지를 한다":"감전을 막으려면 설비를 점검하고 접지를 합니다.","체온 · 혈압 · 맥박수가 내린다":"밤에는 몸의 활동 수치가 내려갑니다.","체온 · 혈압 · 맥박수가 오른다":"낮 동안에는 몸의 활동 수치가 올라갑니다.","체인블럭과 도르래는 양중기가 아니다":"체인블록과 도르래는 양중기에 포함되지 않습니다.","초과하는 하중을 걸지 않고 작업자가 기중자재에 올라타지 않는다":"크레인은 정해진 하중 이하로 쓰고 사람이 타지 않습니다.","초기압력이 높을수록 증가하고 산소 농도가 큰 혼합기에서 더 높다":"처음 압력이 높고 산소가 많을수록 폭발 압력이 커집니다.","초당 10m 이상이면 중지한다":"철골 작업은 순간 바람이 이 세기 이상이면 위험하여 멈춥니다.","초점-필름간 거리는 인자가 아니다":"이 거리는 콘트라스트가 아닌 선명도에 관계됩니다.","최고사용압력 이하에서 작동하는 압력방출장치를 설치한다":"압력용기에는 허용 압력 이하에서 열리는 방출 장치를 달아야 합니다.","최대치수와 최소치수를 기준으로 한 설계이다":"극단치 설계는 가장 큰 사람과 작은 사람에게 맞도록 설계합니다.","최대하중 0.25톤 미만 승강기":"이 정도로 작은 승강기는 양중기에 포함되지 않습니다.","최상층 및 5층 이내마다 둔다":"수평재는 위쪽과 일정 층마다 설치합니다.","최초 폭발이 분진을 비산시켜 2차, 3차 폭발로 번진다":"처음 폭발이 쌓인 분진을 날려 올려 연이어 더 큰 폭발이 일어납니다.","추락재해를 줄이려면 고소작업 자체를 줄인다":"높은 곳 작업을 줄이는 것이 추락 사고를 막는 근본 방법입니다.","충격은 낮고 상용 주파는 높아야 한다":"피뢰기는 번개 같은 충격 전압에서는 낮은 전압에 방전하고 평소 전압에는 견뎌야 합니다.","충격을 가하지 않고 화기를 멀리하며 운반 시 캡을 씌운다":"가스 용기는 부딪히지 않게 하고 불에서 떨어뜨리며 밸브를 보호합니다.","충돌위험 예방대책은 포함 항목이 아니다":"중량물 취급 작업계획서에 충돌 예방 대책은 필수 포함 항목이 아닙니다.","충분한 허용량의 발파기로 규정 스위치를 써서 한다":"전기발파의 점화는 용량이 넉넉한 발파기와 정해진 스위치로 합니다.","충전부를 출입이 쉬운 곳에 설치하지 않는다":"충전부는 사람이 쉽게 닿는 곳에 두지 않습니다.","충전부에서 자력으로 이탈할 수 있는 전류이다":"가수전류는 감전돼도 스스로 손을 뗄 수 있는 한계의 전류입니다.","충전탑과 달리 부식성 유체에 적합하지 않다":"트레이탑은 부식성 유체를 다루기에는 충전탑보다 맞지 않습니다.","취급물질은 정성적 평가 항목이 아니다":"취급하는 물질은 정량적 평가 항목에 속하며 정성적 평가 항목이 아닙니다.","측면 사용 목적 숫돌 외에는 쓰지 않는다":"연삭숫돌의 옆면은 그렇게 쓰도록 만든 숫돌이 아니면 사용하지 않습니다.","치수를 재지 않고 운전 중 백기어를 쓰지 않는다":"선반이 돌고 있을 때 치수를 재거나 백기어를 넣으면 위험합니다.","카가 승강되지 않는 장치를 둔다":"승강기는 문이 열려 있으면 움직이지 못하게 하는 장치가 있어야 합니다.","콘트라스트(명암도)와 명료도이다":"방사선투과검사의 사진 품질에 영향을 주는 요소입니다.","크레인, 리프트, 곤돌라, 승강기이다":"양중기는 물건이나 사람을 들어 올리는 기계입니다.","크레인에 설치하고 전단톱 회전날에는 접촉방지 커버를 설치한다":"철제 햄머는 크레인에 달아 쓰고 회전날에는 가리개를 씌웁니다.","클라이밍폼이고 유로폼은 아니다":"작업발판이 일체로 붙은 거푸집은 클라이밍폼입니다.","타설높이가 높고 다짐이 과할수록":"붓는 높이가 높거나 지나치게 다지면 측압이 커집니다.","타이플레이트형 기둥도 대상이다":"이 형식 기둥도 외력에 약해 확인이 필요합니다.","타인 의견을 수정해 발언할 수 있다":"다른 사람의 의견을 고치거나 덧붙여 새 의견으로 발언해도 됩니다.","타인의 의견에 비판이나 비평을 하지 않는다":"브레인스토밍에서는 남의 의견을 평가하거나 반박하지 않습니다.","탄소섬유 부착공법과 강판압착법":"구조물을 튼튼하게 고치는 보수·보강 공법입니다.","터널지보공 및 복공의 시공방법과 용수 처리방법이 들어간다":"터널 굴착 작업계획서에 포함되는 내용입니다.","토질의 성질, 지층의 분포, 지하수위와 피압수를 파악한다":"지반조사는 땅의 성질과 층 분포와 지하수 상태를 알아내는 조사입니다.","토치가 가열되거나 성능이 불량하거나 석회분이 낀다":"아세틸렌 용접 중 불꽃이 거꾸로 들어가는 이유입니다.","톱날 회전방향 정면에 서서 작업하지 않는다":"톱날이 일감을 튕겨 낼 수 있으므로 정면에 서지 않고 옆에서 작업합니다.","통신선 유도 장해 방지나 기계 보호":"이는 단락접지기구의 목적이 아닙니다.","통전전로, 통전전류 크기, 전격시간이 좌우한다":"감전의 위험 정도는 전류가 흐른 경로와 세기와 시간에 달려 있습니다.","통풍과 저장법으로 열 축적을 막는다":"바람이 통하게 하고 저장 방식을 바꿔 열이 쌓이지 않게 합니다.","통풍이 잘되고 습기·화기·부식성 물질이 없는 곳에 한다":"안전대는 통풍이 되고 불과 약품이 없는 곳에 보관합니다.","통하고 있는 곳의 상태를 점검한다":"와이어로프가 지나가는 부분의 마모와 손상을 확인합니다.","퇴적을 막아도 공기 중에 분산시키지 않는다":"폭발성 분진은 쌓이지 않게 하되 공기 중에 날리지 않게 관리합니다.","투수량이 많고 점토보다 사질토가 크다":"투수계수가 크면 물이 잘 통하며 모래 섞인 흙이 점토보다 큽니다.","특별 교재·교구·설비를 유효하게 쓴다":"Off.J.T는 교육용 특별 설비를 이용할 수 있습니다.","파레토도, 특성요인도, 크로스(클로즈) 분석, 관리도가 있다":"재해 원인을 분석할 때 쓰는 기법들입니다.","파이프 서포트 3개 이상 이어 쓰지 않음":"파이프 서포트를 세 개 이상 이어서 쓰면 약해지므로 쓰지 않습니다.","패널 디스커션 · 포럼 · 버즈 세션":"토의법에 속하는 학습 방식들의 이름입니다.","팽창제와 잭도 해체 수단이다":"건물 해체에는 팽창제나 잭 같은 수단도 쓰입니다.","페이퍼드레인 · 샌드드레인 · 여성토 공법을 쓴다":"점성토 지반의 물을 빼내 단단하게 하는 개량공법입니다.","편견 없이 받아들이고 창의적인 성향이다":"자아실현 욕구가 높은 사람의 특징을 설명한 것입니다.","폐쇄형 외함 구조로 하거나 절연 방호망·덮개를 설치한다":"전기가 흐르는 부분을 막는 함이나 덮개로 접촉을 차단합니다.","폭발위험장소 구분도와 전기단선도가 있다":"공정안전자료 도면에 포함되는 서류입니다.","폭연성 분진 장소는 금속관 공사로 한다":"저압 옥내 배선은 먼지가 들어가지 않는 금속관 공사로 합니다.","폴리에스터·나일론·아크릴 섬유에 효과적이다":"음이온계 활성제는 이런 합성섬유의 정전기를 줄입니다.","폴리에틸렌→셀룰로이드→염화비닐→테프론이다":"(+) 쪽에서 (-) 쪽으로 나열한 물질의 순서입니다.","표면이 수분이나 기름으로 오염되면":"표면이 젖거나 기름이 묻으면 정전기 발생 정도가 달라집니다.","표시 신호를 크고 밝게 하고 불필요한 세부내용을 줄인다":"나이 든 사람이 보기 쉽게 표시를 크고 단순하게 합니다.","표적과 배경 광도 차이를 배경 광도로 나눈 값이다":"광도 대비는 표적이 배경에서 얼마나 뚜렷한지를 비율로 나타냅니다.","표적과 주변의 휘도가 같을 때 최대가 된다":"점멸융합주파수는 대상과 주위의 밝기가 같을 때 가장 큽니다.","표적의 색상은 관련 변수가 아니다":"표적의 색은 피츠의 법칙에 영향을 주지 않습니다.","풍량을 줄이고 토출가스를 흡입측으로 바이패스하거나 대기로 방출한다":"서징을 막으려면 풍량을 조절하고 내보낸 가스를 되돌리거나 내보냅니다.","프레임 중앙부 피트에는 덮개를 씌우고 테이블 이동범위에 방호울을 세운다":"테이블이 움직이는 범위는 울로 막고 구덩이는 덮개를 씌웁니다.","플랜지가 현저히 작거나 회전력이 결합력보다 크면 파괴된다":"숫돌을 잡는 판이 너무 작거나 돌리는 힘이 결합력을 넘으면 깨집니다.","플런저식은 압력방출장치가 아니다":"플런저식은 압력을 방출하는 장치의 종류가 아닙니다.","플레어스택 설치·변경과 전기정격용량 300kW 이상 증가":"이런 변경이 있으면 공정안전보고서를 다시 제출합니다.","플렉시블 피팅을 쓰고 박강전선관은 쓰지 않는다":"움직임이 필요한 연결부에는 구부러지는 피팅을 씁니다.","피부 절연파괴가 발생할 수 있다":"전압이 매우 높으면 피부의 절연 성질이 무너져 저항이 급격히 떨어집니다.","필름 권취, 셀로판제조, 섬유공장에 쓰인다":"자기방전식 제전기는 얇은 필름이나 섬유를 다루는 곳에서 쓰입니다.","필요한 절차를 수행하지 않은 에러이다":"omission error는 해야 할 동작이나 절차를 빠뜨려 생긴 실수입니다.","필요한 정보를 수집하고 현장 의견을 반영한다":"교육계획은 자료를 모으고 현장의 요구를 담아 짭니다.","하루 10회 25kg 이상 들기이다":"근골격계부담작업으로 분류되는 들기 작업의 기준입니다.","하사점을 확인하고 안전블록은 제거하지 않는다":"금형을 붙이기 전에 슬라이드의 가장 낮은 위치를 확인하고 안전블록은 그대로 둡니다.","하이드로포밍 · 압연 · 전조 가공":"재료를 눌러 모양을 만드는 소성가공의 보기입니다.","하지 않으며 시간과 경비를 절약하는 방법을 고려한다":"돌아가는 운반은 하지 않고 시간과 비용을 줄이는 방법을 찾습니다.","학교안전교육은 듀이가 주장한 형식적 교육이다":"학교 안전교육은 형식을 갖춘 교육의 보기로 설명됩니다.","학습 결과를 알려 주고 상벌로 환기시킨다":"배운 결과를 알려 주고 칭찬이나 벌로 의욕을 일으킵니다.","학습과정을 쉽게 알 수 있다":"프로그램 학습은 학습 진행 상태를 눈으로 쉽게 확인할 수 있습니다.","학습 내용은 일정한 간격으로 때때로 연습시킨다":"배운 것을 잊지 않도록 시간 간격을 두고 거듭 연습하게 합니다.","한 꼬임에서 10% 이상 끊어졌으면 쓰지 않는다":"소선이 많이 끊어진 와이어로프는 위험하여 쓰지 않습니다.","한 꼬임에서 10% 이상 끊어진 것은 쓰지 않는다":"항타기 로프는 소선이 많이 끊어지면 사용을 중지합니다.","한 꼬임에서 10% 이상 끊어진 로프는 쓰지 않는다":"소선이 많이 끊어진 와이어로프는 사용을 금지합니다.","한 사람이 많은 의견을 낼 수 있다":"브레인스토밍은 의견 수가 많을수록 좋아 한 사람이 여러 개 말해도 됩니다.","한 지점에 집중하면 다른 곳의 주의가 약해진다":"한곳에 집중하면 다른 곳은 소홀해집니다.","할로겐화합물 소화기를 쓰고 포는 쓰지 않는다":"전기 화재에는 전기가 통하지 않는 소화약제를 쓰고 거품 소화제는 쓰지 않습니다.","함유량과 저장·취급방법을 표시한다":"유해물질 경고표지에는 함량과 보관 및 다루는 법을 적습니다.","합성섬유로 지름 4mm 이상이다":"수인식 방호장치의 손목에 거는 끈 규격입니다.","합성수지, 전분, 소맥분, 철":"이 가루들은 폭연성 분진에 해당하지 않는 보기입니다.","해체를 고려하고 차수성이 낮은 공법은 선택하지 않는다":"나중에 철거하기 쉬워야 하고 물이 새는 공법은 피합니다.","해체한 거푸집에 박힌 것은 즉시 제거한다":"떼어 낸 거푸집에 못이 남아 있으면 찔릴 수 있어 바로 뺍니다.","행동하기 전에 위험요인을 발견·예방하는 것이다":"선취의 원칙은 일이 일어나기 전에 위험을 먼저 해결하는 것입니다.","행동하기 전에 위험요인을 발견·해결하는 것이다":"선취의 원칙은 일을 시작하기 전에 위험을 먼저 찾아 해결한다는 것입니다.","행정길이 40mm 이상 프레스에 쓴다":"손쳐내기식은 슬라이드가 움직이는 길이가 일정 이상인 프레스에 적용합니다.","행정수 120spm 이상 프레스에는 쓰지 않는다":"분당 행정 수가 너무 많은 프레스에는 손쳐내기식이 맞지 않습니다.","허용응력이 크고 굳은 지층에도 관입하나 내부식성은 작다":"강말뚝은 강도가 크고 딱딱한 땅에도 박히지만 녹슬기 쉽습니다.","혈소판과 혈액응고인자가 증가한다":"스트레스를 받으면 몸이 출혈에 대비해 피가 굳는 성분이 늘어납니다.","혈액의 수분과 염분량이 감소한다":"낮에는 혈액 중 수분과 염분이 줄어드는 경향이 있습니다.","혈액의 수분과 염분량이 증가한다":"밤에는 혈액 중 수분과 염분이 늘어납니다.","호스 마스크와 안전모, 고무장화를 쓴다":"오·폐수 침전조 청소 때는 공기를 호스로 공급받는 마스크 등을 씁니다.","호이스트 스위치와 공기정화장치는 안전장치가 아니다":"이 둘은 타워크레인의 안전장치로 보지 않습니다.","호흡중추 정지와 흉부 수축에 의한 질식":"숨 쉬는 신경이 마비되거나 가슴 근육이 굳어 숨을 못 쉬어 죽을 수도 있습니다.","혼촉 또는 오동작에 의한 감전을 방지한다":"단락접지기구는 작업 중 전기가 갑자기 들어와도 감전되지 않게 합니다.","혼합가스, 분진, 분무, 가스폭발":"기체 상태에서 일어나는 기상폭발의 종류입니다.","화기 사용설비에서 5m 이상 떨어뜨린다":"가스를 모아 둔 곳은 불을 쓰는 설비와 일정 거리 이상 떼어 놓습니다.","화물 이탈에는 이탈 및 역주행 방지장치를 둔다":"컨베이어가 멈추거나 화물이 되돌아 흐르지 않도록 방지 장치를 설치합니다.","화상용 붕대를 감고 파우더나 기름은 바르지 않는다":"화상 부위에는 전용 붕대를 쓰고 가루나 기름을 바르지 않습니다.","화약장전 장소에서 30m 이상 떨어진 곳에서 한다":"도통시험은 화약을 넣은 곳에서 충분히 떨어져서 합니다.","화염방지성능이 있는 통기밸브를 제외하고 설치한다":"인화성 액체 저장탱크에는 화염방지기를 달되 성능이 있는 통기밸브는 예외입니다.","화학설비 · 금속 용해로 · 건조설비":"유해위험방지계획서를 내야 하는 설비의 보기입니다.","화학양론비(양론농도)보다 약간 높은 농도에서 최대가 된다":"폭발 압력은 이론적 혼합비보다 연료가 약간 많을 때 가장 큽니다.","화학적 구조와 결합이 불안정하다":"위험물은 분자 구조가 불안정해 쉽게 반응합니다.","환기설비, 질식 시 응급조치, 작업순서·안전수칙":"밀폐된 장소에서 용접할 때 필요한 특별안전보건교육 내용입니다.","환자를 옆으로 눕히고 호흡이 멎으면 인공호흡한다":"유해물 중독자는 구토물이 막히지 않게 눕히고 숨이 멎으면 인공호흡을 합니다.","활동 가능성이 있는 토석을 제거한다":"무너질 위험이 있는 흙과 돌은 미리 치워 붕괴를 예방합니다.","회로를 개선해 오동작을 막는 것이다":"적극적 대책은 회로를 고쳐 오작동을 일으키지 않게 하는 것입니다.","회전부에 덮개를 씌우고 안전색채를 사용하는 것이다":"외관의 안전화는 겉모양을 위험하지 않게 하는 것입니다.","회전축 등에는 덮개나 건널다리를 설치한다":"동력전달장치의 회전부는 몸이 닿지 않게 가립니다.","회전축의 재질·형상에 맞는 비파괴검사를 해 결함을 확인한다":"고속회전체는 시험하기 전에 축에 눈에 안 보이는 결함이 없는지 검사합니다.","후크 중심에 걸고 2줄 걸이 이상을 쓴다":"짐을 걸 때는 균형을 잡도록 후크 한가운데에 걸고 줄을 여러 가닥 씁니다.","훅 또는 카라비너로 확실히 연결한다":"안전대 연결 부분은 빠지지 않게 확실히 걸어야 합니다.","훈계는 기본과정에 포함되지 않는다":"훈계는 교육의 기본 과정에 들지 않는다는 설명입니다.","휴업일수에 300/365를 곱한다":"일시 전노동불능은 쉰 날수에 비율을 곱해 근로손실일수로 바꿉니다.","흉골에 전류가 흘러 혈압이 약해진다는 설명은 틀리다":"감전 사망 원인을 흉골에 흐르는 전류로 설명한 것은 맞지 않습니다.","흡기·배기 저항이 낮아야 한다":"방진마스크는 숨 쉴 때 저항이 작아야 오래 쓸 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
